const southeastItineraries=[{"attractions":[{"description":"America's largest privately owned home: a 250-room French Renaissance chateau built by George Vanderbilt, set on 8,000 acres of gardens, trails, and farmland. The house tour, gardens, conservatory, and Antler Hill farm village can easily fill a full day.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Biltmore%20Estate%20Asheville%20NC","name":"Biltmore Estate","officialUrl":"https://www.biltmore.com","photos":["assets/southeast/asheville-nc-mountains/attr1-1.jpg","assets/southeast/asheville-nc-mountains/attr1-2.jpg","assets/southeast/asheville-nc-mountains/attr1-3.jpg","assets/southeast/asheville-nc-mountains/attr1-4.jpg"],"price":"$89/adult, $44/child ages 10–16; under 10 free (est.)"},{"description":"The 469-mile scenic drive known as America's favorite drive, hugging ridgelines and valleys through the Appalachians. Near Asheville, the Craggy Gardens and Mount Pisgah sections offer the best overlooks and short family hikes.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Blue%20Ridge%20Parkway%20Asheville%20NC","name":"Blue Ridge Parkway","officialUrl":"https://www.nps.gov/blri","photos":["assets/southeast/asheville-nc-mountains/attr2-1.jpg","assets/southeast/asheville-nc-mountains/attr2-2.jpg","assets/southeast/asheville-nc-mountains/attr2-3.jpg","assets/southeast/asheville-nc-mountains/attr2-4.jpg"],"price":"Free (est.)"},{"description":"A 434-acre garden and nature preserve with formal gardens, a renowned bonsai collection, and 10 miles of hiking and biking trails. The hands-on discovery areas and seasonal exhibits make it a gentle, shady half-day for families.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=North%20Carolina%20Arboretum%20Asheville%20NC","name":"The North Carolina Arboretum","officialUrl":"https://www.ncarboretum.org","photos":["assets/southeast/asheville-nc-mountains/attr3-1.jpg","assets/southeast/asheville-nc-mountains/attr3-2.jpg","assets/southeast/asheville-nc-mountains/attr3-3.jpg","assets/southeast/asheville-nc-mountains/attr3-4.jpg"],"price":"$20/vehicle parking (est.)"},{"description":"A 315-foot rock monolith rising over Hickory Nut Gorge with a mountaintop elevator and stair climb to 75-mile views. The park also holds 404-foot Hickory Nut Falls via an easy 1.5-mile trail — a great payoff-to-effort ratio for kids.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Chimney%20Rock%20State%20Park%20NC","name":"Chimney Rock State Park","officialUrl":"https://www.chimneyrockpark.com","photos":["assets/southeast/asheville-nc-mountains/attr4-1.jpg","assets/southeast/asheville-nc-mountains/attr4-2.jpg","assets/southeast/asheville-nc-mountains/attr4-3.jpg","assets/southeast/asheville-nc-mountains/attr4-4.jpg"],"price":"$17/adult, $8/youth ages 5–15 (est.)"}],"bestSeason":"April–October","budget":1450,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days; lodging and gas not included.","days":3,"destination":"Asheville, NC","driveNotes":"Asheville is about 2 hours from Charlotte and 4 from Atlanta via I-40, which crosses the mountains — beautiful but curvy, so plan extra time. Downtown and the River Arts District are easy to park in; Biltmore and Chimney Rock need a car. In fall, book lodging early — leaf season fills up fast.","familyFriendly":"Best for ages 5+. Biltmore's house tour is long for little legs — the gardens and farm animals are the kid payoff. Chimney Rock's stairs are steep; carriers beat strollers.","heroPhoto":"assets/southeast/asheville-nc-mountains/hero.jpg","highlights":["Tour the 250-room Biltmore House and roam its gardens and farm village","Drive the Blue Ridge Parkway with stops at Craggy Gardens overlooks","Hike to the top of Chimney Rock for a 75-mile view","Wander the gardens and trails of The North Carolina Arboretum","Sample Southern comfort food on walkable downtown Asheville"],"id":"asheville-nc-mountains","interests":["family","nature","outdoors","scenic","food"],"itinerary":[{"afternoon":{"cost":"Included with estate ticket (est.)","description":"Picnic or grab lunch on the grounds, then stroll the Italian and walled gardens. Finish at Antler Hill Village and Farm, where kids can meet goats, chickens, and draft horses while the grown-ups sample the winery.","stop":"Biltmore gardens + Antler Hill Village","time":"12:30 PM – 5:00 PM"},"day":1,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Park once and wander the street performers and shops of downtown. Dinner at a family-friendly Southern spot, then an early night — tomorrow starts on the Parkway.","stop":"Downtown Asheville","time":"6:00 PM – 8:30 PM"},"morning":{"cost":"$89/adult, $44/child (ages 10–16); under 10 free (est.)","description":"Start at America's largest privately owned home. The self-guided house tour takes about two hours and winds past the grand staircase, the library, and the indoor pool. Kids get an activity booklet at the ticket center that turns the tour into a scavenger hunt.","stop":"Biltmore Estate — House tour","time":"9:00 AM – 12:00 PM"},"title":"Biltmore Day"},{"afternoon":{"cost":"$20/vehicle parking (est.)","description":"Back down near the Parkway entrance, 434 acres of gardens, bonsai exhibits, and easy trails. The quilt garden and the model train area are kid favorites. Bring swimsuits in summer — there's a stream kids love to splash in.","stop":"The North Carolina Arboretum","time":"1:30 PM – 4:30 PM"},"day":2,"evening":{"cost":"$50–$75 for dinner (est.)","description":"Watch artists at work in converted warehouses along the French Broad River, then grab tacos or barbecue for a casual dinner.","stop":"Asheville's River Arts District","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"Free (est.)","description":"Hop on the Parkway at the Folk Art Center and drive south toward Craggy Gardens, stopping at every overlook that catches your eye. The Craggy Gardens trail is a short, kid-doable mile round-trip with huge payoff views. Pack the camera and a light jacket — it's 10 degrees cooler up here.","stop":"Blue Ridge Parkway scenic drive","time":"9:00 AM – 12:30 PM"},"title":"Blue Ridge Parkway"},{"afternoon":{"cost":"$10/adult beach entry (est.)","description":"Cool off with a swim at Lake Lure's small public beach, or rent a pedal boat. It's the lake from Dirty Dancing, if the grown-ups want a photo op.","stop":"Lake Lure","time":"1:30 PM – 4:30 PM"},"day":3,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Head back to Asheville for one last mountain-town dinner before the drive home.","stop":"Farewell dinner in Asheville","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"$17/adult, $8/youth (ages 5–15) (est.)","description":"A 25-mile drive southeast brings you to the park's famous 315-foot rock monolith. Take the elevator (yes, inside the mountain) or climb the 500 steps — either way the 75-mile view from the top is unforgettable. The Hickory Nut Falls trail at the base is an easy 1.5-mile walk.","stop":"Chimney Rock State Park","time":"9:00 AM – 1:00 PM"},"title":"Chimney Rock"}],"lat":35.5973,"lng":-82.553,"overview":"Asheville is the rare mountain town that keeps kids wide-eyed all day: America's largest private home at Biltmore, waterfall hikes you can finish before lunch, and a parkway made for slow scenic drives with endless overlooks. The downtown is walkable and full of family-friendly Southern food. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Asheville Museum of Science — hands-on STEM exhibits and a climbing structure downtown","Asheville Pinball Museum — pay one entry, play dozens of vintage pinball machines all day","Asheville Art Museum — family art labs and a rooftop with mountain views"],"region":"Blue Ridge Mountains","related":["blue-ridge-ga-mountains","greenville-sc-downtown","outer-banks-nc-coastal"],"restaurants":[{"detail":"Downtown Southern comfort food — fried chicken, biscuits, and a kids' menu that goes beyond nuggets.","name":"Tupelo Honey","price":"$$"},{"detail":"Creative tacos in the River Arts District with riverside seating and plenty of kid-approved options.","name":"White Duck Taco Shop","price":"$"},{"detail":"Beloved local barbecue joint in Arden with ribs, brisket, and famous blueberry chipotle sauce.","name":"12 Bones Smokehouse","price":"$$"}],"state":"NC","stateName":"North Carolina","tagline":"Castles, waterfalls, and mile-high views in the Blue Ridge Mountains.","title":"Asheville, NC: Three-Day Mountain Escape","tripType":"mountain retreat","imageAsset":"assets/southeast/asheville-nc-mountains/hero.jpg"},{"attractions":[{"description":"Where the Wright brothers made the first powered flights in 1903. Climb Big Kill Devil Hill to the 60-foot granite monument, walk the flight-line markers, and let the kids fly kites on the same breezy field that lifted the Flyer. The visitor center holds a full-size replica of the 1903 plane.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Wright%20Brothers%20National%20Memorial%20Kill%20Devil%20Hills%20NC","name":"Wright Brothers National Memorial","officialUrl":"https://www.nps.gov/wrbr","photos":["assets/southeast/outer-banks-nc-coastal/attr1-1.jpg","assets/southeast/outer-banks-nc-coastal/attr1-2.jpg","assets/southeast/outer-banks-nc-coastal/attr1-3.jpg","assets/southeast/outer-banks-nc-coastal/attr1-4.jpg"],"price":"$10/person ages 16+; 15 and under free (est.)"},{"description":"The tallest living sand dune system on the Atlantic coast, with 427 acres of bare sand to climb, roll down, and hang-glide over. The soft sand, huge views, and free entry make it the Outer Banks' best free half-day — go at sunset when the sand glows.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Jockey%27s%20Ridge%20State%20Park%20Nags%20Head%20NC","name":"Jockey's Ridge State Park","officialUrl":"https://www.ncparks.gov/state-parks/jockeys-ridge-state-park","photos":["assets/southeast/outer-banks-nc-coastal/attr2-1.jpg","assets/southeast/outer-banks-nc-coastal/attr2-2.jpg","assets/southeast/outer-banks-nc-coastal/attr2-3.jpg","assets/southeast/outer-banks-nc-coastal/attr2-4.jpg"],"price":"Free (est.)"},{"description":"America's tallest brick lighthouse at 198 feet, with its famous black-and-white barber-pole stripes. The 257-step climb is a rite of passage — kids love counting the steps — and the view from the top stretches from the ocean to Pamlico Sound.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Cape%20Hatteras%20Lighthouse%20Buxton%20NC","name":"Cape Hatteras Lighthouse","officialUrl":"https://www.nps.gov/caha","photos":["assets/southeast/outer-banks-nc-coastal/attr3-1.jpg","assets/southeast/outer-banks-nc-coastal/attr3-2.jpg","assets/southeast/outer-banks-nc-coastal/attr3-3.jpg","assets/southeast/outer-banks-nc-coastal/attr3-4.jpg"],"price":"Climbing tickets $11/adult, $6/child (est.)"},{"description":"A 1,000-foot concrete pier stretching into the Atlantic with panoramic decks, an aquarium with touch tanks, and some of the best sunrise views on the Banks. Strolling is free and fishing needs only a daily pass — no license required.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Jennette%27s%20Pier%20Nags%20Head%20NC","name":"Jennette's Pier","officialUrl":"https://www.jennettespier.net","photos":["assets/southeast/outer-banks-nc-coastal/attr4-1.jpg","assets/southeast/outer-banks-nc-coastal/attr4-2.jpg","assets/southeast/outer-banks-nc-coastal/attr4-3.jpg","assets/southeast/outer-banks-nc-coastal/attr4-4.jpg"],"price":"Pier walking free; fishing passes from $6 (est.)"}],"bestSeason":"May–October","budget":1650,"budgetNote":"Estimate for 2 adults + 2 kids over 4 days; lodging and gas not included.","days":4,"destination":"Outer Banks, NC","driveNotes":"The Outer Banks is a 4- to 5-hour drive from Raleigh and about 6 from Richmond — most families arrive via the Wright Memorial Bridge from the north. NC-12 is the single road linking the towns; it can flood near Oregon Inlet in storms, so check conditions before a Hatteras day trip. Parking at beach accesses is free and plentiful except in peak summer.","familyFriendly":"Great for all ages, including toddlers. Beaches are wide and gently sloped, and the Wright Brothers field and Jockey's Ridge are stroller-free zones best done with carriers or bare feet.","heroPhoto":"assets/southeast/outer-banks-nc-coastal/hero.jpg","highlights":["Climb Big Kill Devil Hill where the Wright brothers first flew","Roll down the giant dunes of Jockey's Ridge at sunset","Climb the 257 steps of Cape Hatteras Lighthouse","Fish or stroll the 1,000-foot Jennette's Pier","Spend lazy afternoons on the wide beaches of Nags Head"],"id":"outer-banks-nc-coastal","interests":["family","beaches","outdoors","nature","historical-sites"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Head to the tallest living dune system on the Atlantic coast. Kids can climb the 80-foot dunes, roll down, and watch hang gliders launch. Bring sandals you can shake out — the sand gets everywhere.","stop":"Jockey's Ridge State Park","time":"3:00 PM – 6:00 PM"},"day":1,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Watch the sun sink over Roanoke Sound from a waterfront restaurant, then an early night — beach mornings start early.","stop":"Dinner on the sound side","time":"6:30 PM – 8:30 PM"},"morning":{"cost":"$10/person ages 16+; 15 and under free (est.)","description":"Start where powered flight began. Walk the flight-line markers where each 1903 flight landed, climb Big Kill Devil Hill to the granite monument, and bring kites — the steady breeze on this field is the same one that lifted the Flyer.","stop":"Wright Brothers National Memorial","time":"9:00 AM – 12:00 PM"},"title":"First in Flight"},{"afternoon":{"cost":"Pier walking free (est.)","description":"Stroll the 1,000-foot pier, peek at the touch tanks in the small aquarium, and watch fishermen haul in their catch. The end of the pier is the best people-watching on the beach.","stop":"Jennette's Pier","time":"2:00 PM – 4:00 PM"},"day":2,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Classic Outer Banks seafood — shrimp, crab cakes, and hushpuppies — at a Nags Head institution.","stop":"Seafood dinner in Nags Head","time":"6:00 PM – 8:00 PM"},"morning":{"cost":"Free (est.)","description":"Claim your spot on the wide, lifeguarded beach at Nags Head. The gentle slope makes this one of the most kid-friendly beaches on the East Coast — build castles, boogie board, and hunt for shells.","stop":"Nags Head beach day","time":"9:00 AM – 1:00 PM"},"title":"Beach Day"},{"afternoon":{"cost":"Free (est.)","description":"Cool off with a swim at the lifeguarded beach near the lighthouse, then browse the lighthouse keepers' quarters museum. The drive back north along the ocean is half the fun.","stop":"Hatteras beach time","time":"1:30 PM – 4:00 PM"},"day":3,"evening":{"cost":"$50–$75 for dinner (est.)","description":"Stop in Manteo on the way back for dinner on the waterfront — a charming little harbor town made for an evening stroll.","stop":"Dinner in Manteo","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"Climbing tickets $11/adult, $6/child (est.)","description":"Drive an hour south on NC-12 through Pea Island National Wildlife Refuge — stop for the boardwalk and the birdlife. Then climb the 257 steps of the black-and-white-striped Cape Hatteras Lighthouse, America's tallest brick lighthouse.","stop":"Cape Hatteras day trip","time":"8:30 AM – 1:00 PM"},"title":"Hatteras Day"},{"afternoon":{"cost":"$12/adult, $10/child (est.)","description":"The Roanoke Island aquarium has sharks, stingrays, and a great touch pool — a perfect indoor break. Then wander the waterfront before the drive home.","stop":"North Carolina Aquarium on Roanoke Island","time":"1:00 PM – 3:30 PM"},"day":4,"evening":{"cost":"$50–$75 for dinner (est.)","description":"One last beach-town dinner on the way off the island.","stop":"Farewell dinner","time":"5:00 PM – 7:00 PM"},"morning":{"cost":"$6–$10/person (est.)","description":"Tour the site of England's first New World colony and stroll the Elizabethan Gardens next door — shady, quiet, and beautiful. Kids get a junior ranger-style activity sheet at the visitor center.","stop":"Fort Raleigh National Historic Site","time":"9:00 AM – 12:00 PM"},"title":"Roanoke Island"}],"lat":35.9996,"lng":-75.648,"overview":"The Outer Banks is a 200-mile string of barrier islands where history and beach time share the same sand: the Wright brothers' first flights, giant dunes you can climb for free, and lighthouses you can climb for a few dollars. The beaches are wide and gentle — ideal for little kids. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["North Carolina Aquarium on Roanoke Island — sharks, rays, and touch tanks","Graveyard of the Atlantic Museum in Hatteras — shipwreck stories and artifacts","Wright Brothers visitor center — indoor flight exhibits and a full-size 1903 Flyer replica"],"region":"Outer Banks","related":["wilmington-nc-coastal","myrtle-beach-sc-coastal","asheville-nc-mountains"],"restaurants":[{"detail":"Nags Head seafood institution since 1946 — crab cakes, hushpuppies, and ocean views.","name":"Owen's Restaurant","price":"$$"},{"detail":"Casual local favorite for breakfast and lunch — big pancakes the kids will remember.","name":"Sam & Omie's","price":"$"},{"detail":"Beachy, laid-back spot in Nags Head with Caribbean-inspired dishes and live music.","name":"Tortugas' Lie","price":"$$"}],"state":"NC","stateName":"North Carolina","tagline":"Where flight began and the dunes meet the sea.","title":"Outer Banks, NC: Four-Day Coastal Escape","tripType":"coastal escape","imageAsset":"assets/southeast/outer-banks-nc-coastal/hero.jpg"},{"attractions":[{"description":"One of the top hands-on science museums in the Southeast, with an indoor rainforest, a huge aquarium, and a dedicated KidScience zone for ages 0–6. The live science shows and the 7-story IMAX-style dome theater can fill a full day without a dull minute.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Discovery%20Place%20Science%20Charlotte%20NC","name":"Discovery Place Science","officialUrl":"https://www.discoveryplace.org","photos":["assets/southeast/charlotte-nc-city/attr1-1.jpg","assets/southeast/charlotte-nc-city/attr1-2.jpg","assets/southeast/charlotte-nc-city/attr1-3.jpg","assets/southeast/charlotte-nc-city/attr1-4.jpg"],"price":"$20/adult, $15/child (est.)"},{"description":"A 400-acre theme park straddling the NC/SC line with 14 roller coasters, including the 325-foot Fury 325 giga coaster, plus the Carolina Harbor water park and a huge Camp Snoopy kids' area. A full day easily, two if your kids are coaster people.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Carowinds%20Charlotte%20NC","name":"Carowinds","officialUrl":"https://www.carowinds.com","photos":["assets/southeast/charlotte-nc-city/attr2-1.jpg","assets/southeast/charlotte-nc-city/attr2-2.jpg","assets/southeast/charlotte-nc-city/attr2-3.jpg","assets/southeast/charlotte-nc-city/attr2-4.jpg"],"price":"$65/person day ticket (est.)"},{"description":"The world's largest man-made whitewater river on 1,300 wooded acres, plus flatwater kayaking, 50+ miles of trails, zip lines, and a climbing center. The day-pass model means you can mix rafting with trails and ropes courses in one visit.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=U.S.%20National%20Whitewater%20Center%20Charlotte%20NC","name":"U.S. National Whitewater Center","officialUrl":"https://www.usnwc.org","photos":["assets/southeast/charlotte-nc-city/attr3-1.jpg","assets/southeast/charlotte-nc-city/attr3-2.jpg","assets/southeast/charlotte-nc-city/attr3-3.jpg","assets/southeast/charlotte-nc-city/attr3-4.jpg"],"price":"$59–$89/person day pass (est.)"},{"description":"A shrine to stock-car racing in the heart of Uptown, with real race cars, racing simulators, a pit-crew challenge, and the Hall of Honor. Even non-fans get hooked on the interactive exhibits — kids can change a tire against the clock.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=NASCAR%20Hall%20of%20Fame%20Charlotte%20NC","name":"NASCAR Hall of Fame","officialUrl":"https://www.nascarhall.com","photos":["assets/southeast/charlotte-nc-city/attr4-1.jpg","assets/southeast/charlotte-nc-city/attr4-2.jpg","assets/southeast/charlotte-nc-city/attr4-3.jpg","assets/southeast/charlotte-nc-city/attr4-4.jpg"],"price":"$27/adult, $20/child (est.)"}],"bestSeason":"March–November","budget":1550,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days; lodging and gas not included.","days":3,"destination":"Charlotte, NC","driveNotes":"Charlotte sits at the crossroads of I-77 and I-85, about 3.5 hours from Atlanta and 2.5 from Raleigh. Uptown attractions cluster within walking distance of each other; Carowinds and the Whitewater Center are 20–30 minutes out. Traffic on I-77 can be brutal at rush hour — plan park days to avoid it.","familyFriendly":"Best for ages 5+. Carowinds' coasters skew older (many have 48–54\" height minimums), but Camp Snoopy and Carolina Harbor are perfect for little kids. Discovery Place has a dedicated 0–6 zone.","heroPhoto":"assets/southeast/charlotte-nc-city/hero.jpg","highlights":["Ride 14 coasters at Carowinds, including the 325-foot Fury 325","Raft the world's largest man-made whitewater course","Explore the indoor rainforest at Discovery Place Science","Race simulators and pit-crew challenges at the NASCAR Hall of Fame","Easy day-trip access to both mountains and the coast"],"id":"charlotte-nc-city","interests":["family","amusement-parks","museums","outdoors"],"itinerary":[{"afternoon":{"cost":"Included in day ticket (est.)","description":"Cool off at Carolina Harbor, the 27-acre water park inside Carowinds, with wave pools, slides, and a lazy river. Dry off on the kiddie coasters before the park closes.","stop":"Carowinds — Carolina Harbor water park","time":"2:00 PM – 6:00 PM"},"day":1,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Head to the NoDa arts district for murals, music, and a family-friendly dinner — tacos, pizza, or Southern comfort.","stop":"Dinner in NoDa","time":"6:30 PM – 8:30 PM"},"morning":{"cost":"$65/person (est.)","description":"Arrive at opening and hit the big coasters before lines build — Fury 325, Copperhead Strike, and Intimidator 305. Camp Snoopy keeps younger kids happy with gentler rides while the grown-ups take turns.","stop":"Carowinds","time":"10:00 AM – 2:00 PM"},"title":"Coaster Day"},{"afternoon":{"cost":"Included with museum ticket (est.)","description":"After lunch, walk two blocks to the NASCAR Hall of Fame. Race the simulators, try the pit-crew tire-change challenge, and see legendary cars up close.","stop":"NASCAR Hall of Fame","time":"1:30 PM – 4:30 PM"},"day":2,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Ride the free Gold Line streetcar to dinner, then take a twilight stroll through Romare Bearden Park with the skyline lit up behind the kids' play fountains.","stop":"Uptown evening","time":"5:30 PM – 8:30 PM"},"morning":{"cost":"$20/adult, $15/child (est.)","description":"Start in Uptown at Discovery Place Science. The indoor rainforest and the aquarium wow all ages; KidScience is a dream zone for under-6s. Catch a live science show before lunch.","stop":"Discovery Place Science","time":"9:00 AM – 1:00 PM"},"title":"Uptown Day"},{"afternoon":{"cost":"Included in day pass (est.)","description":"After rafting, the ropes courses, zip lines, and climbing walls keep the adrenaline going. Younger kids love the flatwater kayaking and the nature trails.","stop":"Whitewater Center — ropes, zip lines, trails","time":"1:00 PM – 5:00 PM"},"day":3,"evening":{"cost":"$60–$90 for dinner (est.)","description":"One last Charlotte dinner before heading home.","stop":"Farewell dinner","time":"6:00 PM – 8:00 PM"},"morning":{"cost":"$59–$89/person day pass (est.)","description":"Book a guided family rafting session on the man-made whitewater channels — no experience needed, and wetsuits are provided in cool weather. The whole family rides together with a guide.","stop":"U.S. National Whitewater Center — rafting","time":"9:30 AM – 12:30 PM"},"title":"Whitewater Day"}],"lat":35.2271,"lng":-80.8431,"overview":"Charlotte packs a surprising punch for families: a world-class science museum, a 400-acre theme park, the world's largest man-made whitewater course, and a shrine to NASCAR — all within 30 minutes of each other. It's an easy drive from anywhere in the Carolinas. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Discovery Place Science — easily a full indoor day","NASCAR Hall of Fame — all indoors, simulators and exhibits","SEA LIFE Charlotte-Concord Aquarium — underwater tunnels 25 minutes north in Concord"],"region":"Piedmont","related":["raleigh-durham-nc-triangle","asheville-nc-mountains","atlanta-ga-city"],"restaurants":[{"detail":"Beloved Charlotte BBQ institution — chopped pork, hushpuppies, and sweet tea in a no-frills setting.","name":"Bill Spoon's Barbecue","price":"$"},{"detail":"Gourmet hot dogs and house-made sodas in Plaza Midwood — a kid-pleaser with local flavor.","name":"The Penguin","price":"$"},{"detail":"Uptown Latin favorite for empanadas and Cuban sandwiches in a lively, family-friendly space.","name":"Cabo Fish Taco","price":"$$"}],"state":"NC","stateName":"North Carolina","tagline":"Coasters, whitewater, and racing in the Queen City.","title":"Charlotte, NC: Three-Day City Adventure","tripType":"city adventure","imageAsset":"assets/southeast/charlotte-nc-city/hero.jpg"},{"attractions":[{"description":"The Southeast's largest natural history museum — and it's free. Four floors of dinosaurs, live animals, a tropical butterfly conservatory, and the Nature Research Center where you can watch real scientists at work. The giant T. rex \"Acro\" skeleton stops every kid in their tracks.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=North%20Carolina%20Museum%20of%20Natural%20Sciences%20Raleigh%20NC","name":"North Carolina Museum of Natural Sciences","officialUrl":"https://www.naturalsciences.org","photos":["assets/southeast/raleigh-durham-nc-triangle/attr1-1.jpg","assets/southeast/raleigh-durham-nc-triangle/attr1-2.jpg","assets/southeast/raleigh-durham-nc-triangle/attr1-3.jpg","assets/southeast/raleigh-durham-nc-triangle/attr1-4.jpg"],"price":"Free (est.)"},{"description":"The world's largest natural-habitat zoo, set on 2,600 wooded acres in Asheboro — an easy day trip from Raleigh or Durham. Animals roam in sprawling, landscape-like habitats: elephants, gorillas, polar bears, and lions. Plan a full day; it's a lot of walking.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=North%20Carolina%20Zoo%20Asheboro%20NC","name":"North Carolina Zoo","officialUrl":"https://www.nczoo.org","photos":["assets/southeast/raleigh-durham-nc-triangle/attr2-1.jpg","assets/southeast/raleigh-durham-nc-triangle/attr2-2.jpg","assets/southeast/raleigh-durham-nc-triangle/attr2-3.jpg","assets/southeast/raleigh-durham-nc-triangle/attr2-4.jpg"],"price":"$15/adult, $11/child (est.)"},{"description":"Durham's beloved 84-acre science playground: 2 miles of outdoor trails, a butterfly house, farm animals, dinosaurs, and the Hideaway Woods nature play area where kids build forts and splash in streams. Science here is gloriously hands-on and muddy.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Museum%20of%20Life%20and%20Science%20Durham%20NC","name":"Museum of Life and Science","officialUrl":"https://www.lifeandscience.org","photos":["assets/southeast/raleigh-durham-nc-triangle/attr3-1.jpg","assets/southeast/raleigh-durham-nc-triangle/attr3-2.jpg","assets/southeast/raleigh-durham-nc-triangle/attr3-3.jpg","assets/southeast/raleigh-durham-nc-triangle/attr3-4.jpg"],"price":"$25/adult, $20/child (est.)"},{"description":"One of America's oldest amusement parks (est. 1887), this Raleigh gem has a hand-carved 1920s carousel, a pint-sized train, kiddie boats, and pedal boats on the lake. Rides cost about a dollar each — the cheapest thrills in the Triangle.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Pullen%20Park%20Raleigh%20NC","name":"Pullen Park","officialUrl":"https://www.raleighnc.gov/parks","photos":["assets/southeast/raleigh-durham-nc-triangle/attr4-1.jpg","assets/southeast/raleigh-durham-nc-triangle/attr4-2.jpg","assets/southeast/raleigh-durham-nc-triangle/attr4-3.jpg","assets/southeast/raleigh-durham-nc-triangle/attr4-4.jpg"],"price":"Free entry; rides ~$1–$2 each (est.)"}],"bestSeason":"March–November","budget":1100,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days; lodging and gas not included.","days":3,"destination":"Raleigh-Durham, NC","driveNotes":"Raleigh and Durham are 25 minutes apart via I-40, and the NC Zoo in Asheboro is about 75 minutes west — an easy day trip. Downtown Raleigh is compact and walkable; everything else needs a car. Traffic on I-40 between the cities gets heavy at rush hour.","familyFriendly":"Excellent for all ages, including toddlers. The Museum of Natural Sciences is free and stroller-friendly; the NC Zoo is a lot of walking, so bring a stroller or rent one there.","heroPhoto":"assets/southeast/raleigh-durham-nc-triangle/hero.jpg","highlights":["Meet dinosaurs and live butterflies at the free Museum of Natural Sciences","Roam the world's largest natural-habitat zoo in Asheboro","Get muddy at the Museum of Life and Science's nature play area","Ride a 1920s carousel at historic Pullen Park","Two cities, one easy trip — Raleigh's museums plus Durham's science center"],"id":"raleigh-durham-nc-triangle","interests":["family","museums","nature","outdoors"],"itinerary":[{"afternoon":{"cost":"~$1–$2 per ride (est.)","description":"Ride the 1920s carousel, chug around the lake on the kiddie train, and rent pedal boats. The playground and the shade trees make this the perfect low-key afternoon.","stop":"Pullen Park","time":"2:00 PM – 5:00 PM"},"day":1,"evening":{"cost":"$50–$75 for dinner (est.)","description":"Dinner in Raleigh's Warehouse District or Glenwood South — plenty of family-friendly options within walking distance of downtown.","stop":"Dinner in downtown Raleigh","time":"6:00 PM – 8:00 PM"},"morning":{"cost":"Free (est.)","description":"Four floors of dinosaurs, live animals, and a walk-through butterfly conservatory — all free. The Nature Research Center lets kids watch real scientists through glass walls. Don't miss the giant T. rex skeleton.","stop":"North Carolina Museum of Natural Sciences","time":"9:30 AM – 1:00 PM"},"title":"Raleigh Museum Day"},{"afternoon":{"cost":"Included with museum ticket (est.)","description":"After lunch, explore the outdoor wonders: the butterfly house, the farmyard with goats and alpacas, and Hideaway Woods, where kids build forts and dam the stream. Bring a change of clothes.","stop":"Museum of Life and Science — outdoors","time":"1:00 PM – 4:30 PM"},"day":2,"evening":{"cost":"$50–$75 for dinner (est.)","description":"Durham's American Tobacco Campus is a great evening stroll — old brick warehouses turned into restaurants and a big grassy lawn for the kids.","stop":"Dinner in Durham","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"$25/adult, $20/child (est.)","description":"Drive to Durham for 84 acres of hands-on science. The indoor exhibits — aerospace, weather, and sound — are a hit, and the dinosaur trail outside has life-size models along a wooded path.","stop":"Museum of Life and Science","time":"9:30 AM – 12:30 PM"},"title":"Durham Science Day"},{"afternoon":{"cost":"Included with zoo ticket (est.)","description":"The Africa side has elephants, gorillas, and lions in huge natural habitats. The tram (small fee) saves little legs. Plan on 4–5 hours total.","stop":"North Carolina Zoo — Africa habitats","time":"1:00 PM – 4:30 PM"},"day":3,"evening":{"cost":"$50–$75 for dinner (est.)","description":"Head back to the Triangle for a farewell dinner.","stop":"Farewell dinner","time":"6:00 PM – 8:00 PM"},"morning":{"cost":"$15/adult, $11/child (est.)","description":"Drive 75 minutes to Asheboro and the world's largest natural-habitat zoo. Start on the North America side — polar bears, alligators, and bison — before the midday heat.","stop":"North Carolina Zoo","time":"9:00 AM – 12:30 PM"},"title":"Zoo Day Trip"}],"lat":35.7796,"lng":-78.6382,"overview":"The Raleigh-Durham Triangle is a stealth-great family trip: a world-class free natural sciences museum, one of the best hands-on science centers in the country, a 1920s carousel park, and the world's largest natural-habitat zoo an hour away. Two cities, one easy long weekend. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["North Carolina Museum of Natural Sciences — four indoor floors, all free","Museum of Life and Science indoor exhibits — aerospace, weather, sound labs","Marbles Kids Museum in downtown Raleigh — built for ages 10 and under"],"region":"The Triangle","related":["charlotte-nc-city","asheville-nc-mountains","columbia-sc-capital"],"restaurants":[{"detail":"Raleigh BBQ legend for chopped pork plates and hushpuppies — fast, cheap, and kid-approved.","name":"The Pit","price":"$$"},{"detail":"Durham breakfast institution with creative pancakes and a line out the door — go early.","name":"Dame's Chicken & Waffles","price":"$$"},{"detail":"Casual taco spot in Raleigh with a great kids' menu and house-made tortillas.","name":"Chubby's Tacos","price":"$"}],"state":"NC","stateName":"North Carolina","tagline":"Free museums, giant zoos, and a century-old carousel.","title":"Raleigh-Durham, NC: Three-Day Triangle Getaway","tripType":"weekend getaway","imageAsset":"assets/southeast/raleigh-durham-nc-triangle/hero.jpg"},{"attractions":[{"description":"A WWII battleship turned floating museum, moored across the Cape Fear River from downtown. Nine decks to explore — gun turrets, the engine room, crew quarters, and the bridge — with an audio tour that keeps kids moving. Climbing the ladders is half the adventure.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Battleship%20North%20Carolina%20Wilmington%20NC","name":"Battleship NORTH CAROLINA","officialUrl":"https://www.battleshipnc.com","photos":["assets/southeast/wilmington-nc-coastal/attr1-1.jpg","assets/southeast/wilmington-nc-coastal/attr1-2.jpg","assets/southeast/wilmington-nc-coastal/attr1-3.jpg","assets/southeast/wilmington-nc-coastal/attr1-4.jpg"],"price":"$14/adult, $6/child (est.)"},{"description":"A classic family beach 20 minutes from downtown — wide sand, gentle surf, lifeguards in summer, and the iconic Crystal Pier. Johnnie Mercer's Pier is great for strolling, and the surf is calm enough for beginner boogie boarders.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Wrightsville%20Beach%20NC","name":"Wrightsville Beach","officialUrl":"https://www.townofwrightsvillebeach.com","photos":["assets/southeast/wilmington-nc-coastal/attr2-1.jpg","assets/southeast/wilmington-nc-coastal/attr2-2.jpg","assets/southeast/wilmington-nc-coastal/attr2-3.jpg","assets/southeast/wilmington-nc-coastal/attr2-4.jpg"],"price":"Free; parking $3–$5/hr (est.)"},{"description":"A compact, beautifully done aquarium 25 minutes south in Kure Beach, with a two-story ocean tank, shark exhibits, and a touch pool where kids can pet stingrays and horseshoe crabs. The albino alligator Luna is a star.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=North%20Carolina%20Aquarium%20at%20Fort%20Fisher%20Kure%20Beach%20NC","name":"North Carolina Aquarium at Fort Fisher","officialUrl":"https://www.ncaquariums.com/fort-fisher","photos":["assets/southeast/wilmington-nc-coastal/attr3-1.jpg","assets/southeast/wilmington-nc-coastal/attr3-2.jpg","assets/southeast/wilmington-nc-coastal/attr3-3.jpg","assets/southeast/wilmington-nc-coastal/attr3-4.jpg"],"price":"$13/adult, $11/child (est.)"},{"description":"67 acres of formal gardens, lakes, and towering live oaks draped in Spanish moss. The famous Airlie Oak is nearly 500 years old, and the spring azalea bloom is spectacular. Kids love the butterfly house and the resident swans.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Airlie%20Gardens%20Wilmington%20NC","name":"Airlie Gardens","officialUrl":"https://www.airliegardens.org","photos":["assets/southeast/wilmington-nc-coastal/attr4-1.jpg","assets/southeast/wilmington-nc-coastal/attr4-2.jpg","assets/southeast/wilmington-nc-coastal/attr4-3.jpg","assets/southeast/wilmington-nc-coastal/attr4-4.jpg"],"price":"$9/adult, $3/child (est.)"}],"bestSeason":"April–October","budget":1150,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days; lodging and gas not included.","days":3,"destination":"Wilmington, NC","driveNotes":"Wilmington is about 2 hours from Raleigh and 3.5 from Charlotte via US-74/76. Everything on this itinerary is within 25 minutes of downtown, so pick one home base. The Riverwalk has easy parking garages; beach parking at Wrightsville fills by late morning in summer — go early.","familyFriendly":"Great for all ages. The battleship has steep ladders that toddlers can't manage alone — baby carriers work, strollers don't. Wrightsville Beach is gentle and lifeguarded in season.","heroPhoto":"assets/southeast/wilmington-nc-coastal/hero.jpg","highlights":["Climb through nine decks of the WWII Battleship NORTH CAROLINA","Swim and boogie board at family-friendly Wrightsville Beach","Pet stingrays at the Fort Fisher aquarium","Wander the azalea gardens and live oaks of Airlie Gardens","Stroll the two-mile Riverwalk past shops and river views"],"id":"wilmington-nc-coastal","interests":["family","beaches","historical-sites","nature"],"itinerary":[{"afternoon":{"cost":"Free; parking $3–$5/hr (est.)","description":"Twenty minutes from downtown, wide sand and gentle surf. Lifeguards patrol in summer, and Johnnie Mercer's Pier is perfect for a stroll. Beginner surfers take lessons at the south end.","stop":"Wrightsville Beach","time":"1:30 PM – 5:00 PM"},"day":1,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Walk the two-mile brick Riverwalk along the Cape Fear, watching the boats, then grab dinner at a riverfront restaurant.","stop":"Wilmington Riverwalk","time":"6:00 PM – 8:30 PM"},"morning":{"cost":"$14/adult, $6/child (est.)","description":"Tour nine decks of this WWII battleship moored across the river from downtown. The audio tour guides you through gun turrets, the engine room, and crew quarters — plan 2–3 hours.","stop":"Battleship NORTH CAROLINA","time":"9:00 AM – 12:00 PM"},"title":"Battleship + Beach"},{"afternoon":{"cost":"Free (est.)","description":"Drive 25 minutes south to Kure Beach for the Civil War fort's earthen mounds and ocean views. The small visitor center has artifacts kids can handle, and the beach next door is quiet.","stop":"Fort Fisher State Historic Site","time":"1:30 PM – 3:30 PM"},"day":2,"evening":{"cost":"$50–$75 for dinner (est.)","description":"Back in Wilmington for dinner in the historic district — fried seafood, Southern cooking, or pizza.","stop":"Dinner in historic Wilmington","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"$13/adult, $11/child (est.)","description":"A compact aquarium with a two-story ocean tank, shark feedings, and touch pools with stingrays and horseshoe crabs. Say hi to Luna, the famous albino alligator. Two hours is plenty.","stop":"North Carolina Aquarium at Fort Fisher","time":"9:30 AM – 12:00 PM"},"title":"Aquarium Day"},{"afternoon":{"cost":"Free (est.)","description":"One more beach session or a carriage ride through the historic district before hitting the road.","stop":"Beach or historic district","time":"1:00 PM – 3:00 PM"},"day":3,"evening":{"cost":"$50–$75 for dinner (est.)","description":"Farewell dinner on the Riverwalk.","stop":"Farewell dinner","time":"5:00 PM – 7:00 PM"},"morning":{"cost":"$9/adult, $3/child (est.)","description":"67 acres of formal gardens under ancient live oaks. The spring azalea bloom is the headline, but the butterfly house, the 500-year-old Airlie Oak, and the resident swans delight year-round.","stop":"Airlie Gardens","time":"9:00 AM – 12:00 PM"},"title":"Gardens Day"}],"lat":34.2257,"lng":-77.9447,"overview":"Wilmington gives families the best of both worlds: a real WWII battleship to climb, a classic beach 20 minutes away, and a charming riverfront downtown in between. Everything is close, the pace is easy, and the seafood is excellent. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["North Carolina Aquarium at Fort Fisher — mostly indoors","Children's Museum of Wilmington — built for ages 10 and under","Cape Fear Museum of History and Science — local history, hands-on exhibits"],"region":"Cape Fear Coast","related":["outer-banks-nc-coastal","myrtle-beach-sc-coastal","charleston-sc-historic"],"restaurants":[{"detail":"Downtown seafood spot with she-crab soup and fried platters in a historic cotton warehouse.","name":"Elijah's Restaurant","price":"$$"},{"detail":"Casual Carolina-style BBQ joint locals swear by — chopped pork and Brunswick stew.","name":"Casey's Buffet","price":"$"},{"detail":"Laid-back taco and tequila bar on the Riverwalk with great people-watching.","name":"Taco Loco","price":"$"}],"state":"NC","stateName":"North Carolina","tagline":"A battleship, a beach, and a riverfront made for strolling.","title":"Wilmington, NC: Three-Day Coastal Getaway","tripType":"coastal escape","imageAsset":"assets/southeast/wilmington-nc-coastal/hero.jpg"},{"attractions":[{"description":"America's oldest public gardens, founded in the 1680s: 60 acres of camellias and azaleas, the Audubon Swamp Garden boardwalk, a petting zoo, and a nature train the kids will beg to ride. Peacocks roam free — the toddlers' favorite residents.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Magnolia+Plantation+and+Gardens+Charleston+SC","name":"Magnolia Plantation and Gardens","officialUrl":"https://www.magnoliaplantation.com","photos":["assets/southeast/charleston-sc-historic/attr1-1.jpg","assets/southeast/charleston-sc-historic/attr1-2.jpg","assets/southeast/charleston-sc-historic/attr1-3.jpg","assets/southeast/charleston-sc-historic/attr1-4.jpg"],"price":"$40/adult, $25/child (est.)"},{"description":"The sea fort where the Civil War began, reached by a scenic ferry from downtown. Ranger talks are pitched at all ages, the museum lays out the story clearly, and kids can earn a junior ranger badge. Book the ferry early in summer — boats sell out.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Fort+Sumter+National+Monument+Charleston+SC","name":"Fort Sumter National Monument","officialUrl":"https://www.nps.gov/fosu","photos":["assets/southeast/charleston-sc-historic/attr2-1.jpg","assets/southeast/charleston-sc-historic/attr2-2.jpg","assets/southeast/charleston-sc-historic/attr2-3.jpg","assets/southeast/charleston-sc-historic/attr2-4.jpg"],"price":"Ferry $38/adult, $24/child (est.); fort entry free"},{"description":"A top-tier aquarium on the harbor with a 43-foot shark tunnel through the 385,000-gallon Great Ocean Tank, a touch tank full of rays, and the Sea Turtle Care Center — a real working hospital where you can watch recovering turtles swim. Plan 3 hours.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=South+Carolina+Aquarium+Charleston+SC","name":"South Carolina Aquarium","officialUrl":"https://www.scaquarium.org","photos":["assets/southeast/charleston-sc-historic/attr3-1.jpg","assets/southeast/charleston-sc-historic/attr3-2.jpg","assets/southeast/charleston-sc-historic/attr3-3.jpg","assets/southeast/charleston-sc-historic/attr3-4.jpg"],"price":"$35/adult, $25/child (est.)"},{"description":"Charleston's front porch on the harbor: 12 acres of lawns, a palmetto-lined pier stretching into the water, and the iconic Pineapple Fountain that kids are allowed to splash in. Free, always open, and the best sunset walk in the city.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Waterfront+Park+Charleston+SC","name":"Waterfront Park","officialUrl":"https://www.charleston-sc.gov/WaterfrontPark","photos":["assets/southeast/charleston-sc-historic/attr4-1.jpg","assets/southeast/charleston-sc-historic/attr4-2.jpg","assets/southeast/charleston-sc-historic/attr4-3.jpg","assets/southeast/charleston-sc-historic/attr4-4.jpg"],"price":"Free (est.)"}],"bestSeason":"March–June, September–November","budget":1650,"budgetNote":"Estimate for 2 adults + 2 kids over 4 days; lodging and gas not included.","days":4,"destination":"Charleston, SC","driveNotes":"Charleston is about 3.5 hours from Charlotte and 2 hours each from Columbia and Savannah, mostly on easy interstates. Downtown is compact and walkable, but bring the car — Magnolia Plantation and the beaches are a 20-minute drive. Garages in the historic district run about $2/hr (est.); street parking is scarce, so park once and walk.","familyFriendly":"Best for ages 4+. The aquarium, fort ferry, and pineapple fountain are toddler-friendly; the plantation gardens are stroller-manageable but bring a carrier for the swamp boardwalk.","heroPhoto":"assets/southeast/charleston-sc-historic/hero.jpg","highlights":["Stand under centuries-old live oaks at Magnolia Plantation's gardens","Ride the ferry across the harbor to Fort Sumter, where the Civil War began","Walk the 43-foot shark tunnel at the South Carolina Aquarium","Pose by the Pineapple Fountain in Waterfront Park","Watch dolphins on a sunset harbor cruise"],"id":"charleston-sc-historic","interests":["family","historical-sites","beaches","food","scenic"],"itinerary":[{"afternoon":{"cost":"$40/adult, $25/child (est.)","description":"Wander the camellia and azalea gardens, cross the boardwalks of the Audubon Swamp Garden, and let the kids ride the Nature Train. Peacocks roam the lawns and the petting zoo has goats and pigs.","stop":"Magnolia Plantation and Gardens","time":"12:30 PM – 4:30 PM"},"day":1,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Stroll the Battery seawall as the light turns golden, then dinner at a family-friendly Southern spot downtown.","stop":"The Battery + dinner","time":"6:00 PM – 8:30 PM"},"morning":{"cost":"$40/adult, $25/child (est.)","description":"Arrive when the gates open to beat the heat and the crowds. The gardens open first and the swamp boardwalk is magical in morning light. Grab the garden map at the entrance — the kids will love checking off the garden 'rooms.'","stop":"Magnolia Plantation and Gardens","time":"9:00 AM – 12:30 PM"},"title":"Garden Day"},{"afternoon":{"cost":"$15–$25/person (est.)","description":"Spot Atlantic bottlenose dolphins and learn harbor history on a relaxed narrated cruise — a great seated breather for little legs.","stop":"Dolphin harbor cruise","time":"2:30 PM – 4:00 PM"},"day":2,"evening":{"cost":"Free (est.)","description":"Walk the palmetto-lined pier and lawns, watch container ships glide by, and snap the family photo at the Pineapple Fountain.","stop":"Waterfront Park","time":"6:00 PM – 7:30 PM"},"morning":{"cost":"$38/adult, $24/child round trip (est.)","description":"Ferry from Liberty Square out to the island fort where the Civil War's first shots were fired. Rangers give kid-friendly talks, and junior ranger badges are a must. Book the first sailing — afternoon boats sell out in summer.","stop":"Fort Sumter National Monument","time":"9:00 AM – 12:00 PM"},"title":"Fort Day"},{"afternoon":{"cost":"Free (est.)","description":"Rainbow Row, the pastel 18th-century homes that are Charleston's most-photographed street. Kids love counting the colors; grab a pastry from a bakery along the way.","stop":"Rainbow Row","time":"1:30 PM – 3:00 PM"},"day":3,"evening":{"cost":"$$","description":"An easygoing dinner downtown with a kids' menu and outdoor seating.","stop":"Dinner downtown","time":"6:00 PM – 7:30 PM"},"morning":{"cost":"$35/adult, $25/child (est.)","description":"Head straight for the Great Ocean Tank and its 43-foot shark tunnel, then the touch tanks and the Sea Turtle Care Center. Three hours flies by here.","stop":"South Carolina Aquarium","time":"9:30 AM – 12:30 PM"},"title":"Aquarium + Old Charleston"},{"afternoon":{"cost":"$16/adult, $8/child (est.)","description":"America's first museum, with a hands-on kids' area, Lowcountry history, and two historic houses included in admission.","stop":"The Charleston Museum","time":"1:00 PM – 3:30 PM"},"day":4,"evening":{"cost":"$70–$100 for dinner (est.)","description":"One last Lowcountry feast — she-crab soup and shrimp and grits — then a final stroll through the French Quarter before the drive home.","stop":"Farewell dinner","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"Free (est.)","description":"One last slow walk through the historic district with breakfast biscuits in hand. Stop at the City Market for souvenirs the kids can pick out themselves.","stop":"French Quarter + City Market","time":"9:00 AM – 12:00 PM"},"title":"Farewell to the Holy City"}],"lat":32.7765,"lng":-79.9311,"overview":"Charleston packs an extraordinary amount of charm into a walkable peninsula: centuries-old gardens, a harbor fort, one of the country's best aquariums, and streets so pretty they look staged. It's a city that rewards slow days — stroller down cobblestone streets, ride a harbor ferry, let the kids splash near the pineapple fountain. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Children's Museum of the Lowcountry — hands-on museum built for under-10s, $14/adult (est.)","Gibbes Museum of Art — family-friendly art museum with free family days, $15/adult (est.)","The Charleston Museum + historic houses — America's first museum, $16/adult (est.)"],"region":"Lowcountry","related":["savannah-ga-city","hilton-head-sc-beach","myrtle-beach-sc-coastal"],"restaurants":[{"detail":"Charleston institution serving Lowcountry seafood with kid-friendly portions in a relaxed, central spot.","name":"Hyman's Seafood","price":"$$"},{"detail":"Classic Southern cooking — fried chicken, shrimp and grits — in a charming Victorian house near the Battery.","name":"Poogan's Porch","price":"$$"},{"detail":"Waterfront spot with harbor views and a simple, kid-approved seafood menu; great for lunch after the aquarium.","name":"Fleet Landing Restaurant & Bar","price":"$$"}],"state":"SC","stateName":"South Carolina","tagline":"Plantations, harbor forts, and the prettiest streets in the South.","title":"Charleston, SC: Four-Day Historic Escape","tripType":"historic getaway","imageAsset":"assets/southeast/charleston-sc-historic/hero.jpg"},{"attractions":[{"description":"Sixty miles of wide, sandy shoreline with gentle surf — the heart of the trip. The oceanfront Boardwalk runs 1.2 miles with arcades, ice cream shops, and the seasonal fireworks shows. Build castles, hunt for shark teeth, and take the obligatory family photo at sunrise.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Myrtle+Beach+Boardwalk+Myrtle+Beach+SC","name":"Myrtle Beach","officialUrl":"https://www.visitmyrtlebeach.com","photos":["assets/southeast/myrtle-beach-sc-coastal/attr1-1.jpg","assets/southeast/myrtle-beach-sc-coastal/attr1-2.jpg","assets/southeast/myrtle-beach-sc-coastal/attr1-3.jpg","assets/southeast/myrtle-beach-sc-coastal/attr1-4.jpg"],"price":"Free (est.)"},{"description":"A 187-foot observation wheel in glass-enclosed, climate-controlled gondolas — so it runs in rain, heat, and December. Ten to twelve slow revolutions give you 20 minutes of coastline views, day or gloriously lit-up night. The Landshark Bar & Grill at the base is an easy dinner.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=SkyWheel+Myrtle+Beach+SC","name":"SkyWheel Myrtle Beach","officialUrl":"https://www.skywheel.com","photos":["assets/southeast/myrtle-beach-sc-coastal/attr2-1.jpg","assets/southeast/myrtle-beach-sc-coastal/attr2-2.jpg","assets/southeast/myrtle-beach-sc-coastal/attr2-3.jpg","assets/southeast/myrtle-beach-sc-coastal/attr2-4.jpg"],"price":"$18/adult, $14/child (est.)"},{"description":"A 350-acre entertainment complex around Lake Broadway with something for every energy level: WonderWorks' upside-down house, mini golf, the aquarium, and dozens of restaurants. Entry is free — you pay per attraction — so it works as a full day or a two-hour evening stroll.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Broadway+at+the+Beach+Myrtle+Beach+SC","name":"Broadway at the Beach","officialUrl":"https://www.broadwayatthebeach.com","photos":["assets/southeast/myrtle-beach-sc-coastal/attr3-1.jpg","assets/southeast/myrtle-beach-sc-coastal/attr3-2.jpg","assets/southeast/myrtle-beach-sc-coastal/attr3-3.jpg","assets/southeast/myrtle-beach-sc-coastal/attr3-4.jpg"],"price":"Free entry; attractions $10–$35 (est.)"},{"description":"Famous for its 340-foot moving walkway through the shark tunnel — you stand still while sharks glide overhead. Ray Bay's stingray touch pool and the penguin encounters keep the under-8 crowd riveted. Arrive at opening to beat the tour buses.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Ripley%27s+Aquarium+of+Myrtle+Beach+SC","name":"Ripley's Aquarium of Myrtle Beach","officialUrl":"https://www.ripleys.com/attractions/ripleysaquariumofmyrtlebeach","photos":["assets/southeast/myrtle-beach-sc-coastal/attr4-1.jpg","assets/southeast/myrtle-beach-sc-coastal/attr4-2.jpg","assets/southeast/myrtle-beach-sc-coastal/attr4-3.jpg","assets/southeast/myrtle-beach-sc-coastal/attr4-4.jpg"],"price":"$50/adult, $35/child (est.)"}],"bestSeason":"May–October","budget":1450,"budgetNote":"Estimate for 2 adults + 2 kids over 4 days; lodging and gas not included.","days":4,"destination":"Myrtle Beach, SC","driveNotes":"Myrtle Beach is about 3 hours from Charlotte, 2.5 from Raleigh, and 4.5 from Atlanta, mostly on US-17 and SC-22 — an easy drive. Once there, everything runs along the beach and Kings Highway; parking is plentiful and most attractions have free lots. In summer, do the beach before 10 AM or after 4 PM to dodge the heat and the crowds.","familyFriendly":"Best for ages 3+. The beach, SkyWheel gondolas, and aquarium are all toddler-friendly; the whole town is built around families, so stroller access and kids' menus are everywhere.","heroPhoto":"assets/southeast/myrtle-beach-sc-coastal/hero.jpg","highlights":["Ride the 187-foot SkyWheel in climate-controlled gondolas","Walk the moving shark tunnel at Ripley's Aquarium","Spend long, lazy mornings on 60 miles of sandy beach","Stroll the 1.2-mile oceanfront Boardwalk at sunset","Sample everything at Broadway at the Beach's lakeside attractions"],"id":"myrtle-beach-sc-coastal","interests":["family","beaches","amusement-parks","food","outdoors"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Unpack, grab groceries, and hit the sand. Build castles, splash in the gentle surf, and hunt for shells — Myrtle's beaches are famous for shark-tooth hunting.","stop":"Beach time","time":"2:00 PM – 5:00 PM"},"day":1,"evening":{"cost":"$18/adult, $14/child (est.)","description":"Ride the SkyWheel at sunset for glowing ocean views, then stroll the Boardwalk for ice cream and arcade games. Summer fireworks light up the sky several nights a week.","stop":"SkyWheel + Boardwalk","time":"6:30 PM – 9:00 PM"},"morning":{"cost":"Free (est.)","description":"Settle in and get your bearings — this is a settle-in morning. If you arrived the night before, start with a beach walk and breakfast at a pancake house.","stop":"Arrival + beach walk","time":"9:00 AM – 12:00 PM"},"title":"Beach Arrival"},{"afternoon":{"cost":"Free (est.)","description":"Back to the beach for the afternoon: boogie boarding, more shell hunting, and an umbrella nap for the grown-ups.","stop":"Beach afternoon","time":"1:30 PM – 4:30 PM"},"day":2,"evening":{"cost":"Free entry; attractions $10–$35 (est.)","description":"Mini golf, the upside-down house, or just a lakeside stroll with ice cream. Everything is lit up and lively after dark.","stop":"Broadway at the Beach","time":"6:00 PM – 9:00 PM"},"morning":{"cost":"$50/adult, $35/child (est.)","description":"Arrive at opening to beat the crowds. The moving shark tunnel is the star, but don't miss the stingray touch pool and the sloth encounters. Three hours is the sweet spot.","stop":"Ripley's Aquarium","time":"9:00 AM – 12:00 PM"},"title":"Aquarium Day"},{"afternoon":{"cost":"$20–$40 for mini golf (est.)","description":"Myrtle Beach is the mini golf capital of the world — pick a themed course (volcanoes, pirates, dinosaurs) and let the kids keep score.","stop":"Mini golf","time":"2:00 PM – 4:00 PM"},"day":3,"evening":{"cost":"$$","description":"A classic seafood dinner on the oceanfront, then one last Boardwalk stroll.","stop":"Dinner + Boardwalk","time":"6:00 PM – 8:30 PM"},"morning":{"cost":"Free (est.)","description":"A full beach morning: swim, sandcastles, and a walk to the pier. Pack a cooler and stay until lunch.","stop":"Beach day","time":"9:00 AM – 12:30 PM"},"title":"Beach + Mini Golf"},{"afternoon":{"cost":"$10–$25/person (est.)","description":"A gentle dolphin cruise before checkout — the boat heads out past the jetties where pods feed.","stop":"Dolphin cruise","time":"12:30 PM – 2:30 PM"},"day":4,"evening":{"cost":"Free (est.)","description":"Hit the road or settle in for one more night.","stop":"Departure","time":"4:00 PM – 6:00 PM"},"morning":{"cost":"Free (est.)","description":"One last beach walk at sunrise, souvenir shopping at the Boardwalk shops, and a pancake-house breakfast.","stop":"Souvenirs + farewell beach","time":"8:30 AM – 11:30 AM"},"title":"Farewell to the Grand Strand"}],"lat":33.6891,"lng":-78.8867,"overview":"Myrtle Beach is the classic family beach town: 60 miles of sandy shoreline, a 1.2-mile oceanfront Boardwalk, a 187-foot observation wheel, and enough mini golf and aquariums to fill a week. It's affordable, easy to navigate, and built entirely around families having fun. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["WonderWorks Myrtle Beach — upside-down interactive science house, $35/adult (est.)","Hollywood Wax Museum Entertainment Center — wax figures plus a mirror maze, $28/adult (est.)","The Children's Museum of South Carolina — hands-on exhibits for under-10s, $10/person (est.)"],"region":"Grand Strand","related":["outer-banks-nc-coastal","charleston-sc-historic","hilton-head-sc-beach"],"restaurants":[{"detail":"Beloved breakfast spot with enormous portions, kid-approved waffles, and a lively family vibe.","name":"Johnny D's Waffles and Bakery","price":"$"},{"detail":"Oceanfront classic serving Lowcountry seafood and she-crab soup with a kids' menu and ocean views.","name":"Sea Captain's House","price":"$$"},{"detail":"Casual burger joint with vintage flair, outdoor seating, and a menu kids genuinely love.","name":"River City Cafe","price":"$"}],"state":"SC","stateName":"South Carolina","tagline":"Sixty miles of sand, a sky-high wheel, and endless family fun.","title":"Myrtle Beach, SC: Four-Day Beach Escape","tripType":"beach vacation","imageAsset":"assets/southeast/myrtle-beach-sc-coastal/hero.jpg"},{"attractions":[{"description":"A 32-acre park in the middle of downtown built around the Reedy River falls. Walk the curved Liberty Bridge for the perfect waterfall view, let the kids splash in the fountains, and stay for a picnic on the lawns. It's free, open daily, and genuinely one of the prettiest urban parks in the South.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Falls+Park+on+the+Reedy+Greenville+SC","name":"Falls Park on the Reedy","officialUrl":"https://www.greenvillesc.gov/241/Falls-Park","photos":["assets/southeast/greenville-sc-downtown/attr1-1.jpg","assets/southeast/greenville-sc-downtown/attr1-2.jpg","assets/southeast/greenville-sc-downtown/attr1-3.jpg","assets/southeast/greenville-sc-downtown/attr1-4.jpg"],"price":"Free (est.)"},{"description":"Three floors of hands-on play built for under-12s: a water table the size of a river, a pint-sized grocery store and bank, a construction zone, and a climbing structure that burns energy fast. A perfect half-day, especially with toddlers and preschoolers.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=The+Children%27s+Museum+of+the+Upstate+Greenville+SC","name":"The Children's Museum of the Upstate","officialUrl":"https://www.tcmupstate.org","photos":["assets/southeast/greenville-sc-downtown/attr2-1.jpg","assets/southeast/greenville-sc-downtown/attr2-2.jpg","assets/southeast/greenville-sc-downtown/attr2-3.jpg","assets/southeast/greenville-sc-downtown/attr2-4.jpg"],"price":"$12/person ages 1+ (est.)"},{"description":"A 22-mile paved greenway along the Reedy River connecting downtown Greenville to Travelers Rest — flat, shaded, and perfect for a family ride. Rent bikes (with tag-alongs and trailers) near Falls Park and pedal out as far as the kids' legs allow, stopping for ice cream on the way back.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Swamp+Rabbit+Trail+Greenville+SC","name":"Swamp Rabbit Trail","officialUrl":"https://www.greenvillesc.gov/316/Swamp-Rabbit-Trail","photos":["assets/southeast/greenville-sc-downtown/attr3-1.jpg","assets/southeast/greenville-sc-downtown/attr3-2.jpg","assets/southeast/greenville-sc-downtown/attr3-3.jpg","assets/southeast/greenville-sc-downtown/attr3-4.jpg"],"price":"Free; bike rentals ~$15–$30 (est.)"},{"description":"A compact, very walkable zoo set in a shady park — giraffes you can feed, lions, and a sweet farmyard area for little ones. You can see everything in 2-3 hours, which is exactly right for younger kids. The giraffe feeding deck is the highlight.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Greenville+Zoo+Greenville+SC","name":"Greenville Zoo","officialUrl":"https://www.greenvillezoo.com","photos":["assets/southeast/greenville-sc-downtown/attr4-1.jpg","assets/southeast/greenville-sc-downtown/attr4-2.jpg","assets/southeast/greenville-sc-downtown/attr4-3.jpg","assets/southeast/greenville-sc-downtown/attr4-4.jpg"],"price":"$12/adult, $8/child (est.)"}],"bestSeason":"March–June, September–November","budget":950,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days; lodging and gas not included.","days":3,"destination":"Greenville, SC","driveNotes":"Greenville sits on I-85, about 1.5 hours from Charlotte and Asheville and 2.5 from Atlanta — an easy weekend drive. Downtown is compact and walkable; park once in a garage (around $1/hr, est.) and stroll. The zoo and museum are 5 minutes from downtown by car; the Swamp Rabbit Trail starts right at Falls Park.","familyFriendly":"Best for ages 3+. Falls Park, the children's museum, and the zoo are all toddler-friendly; the trail is flat and shaded, great with tag-along bikes and trailers.","heroPhoto":"assets/southeast/greenville-sc-downtown/hero.jpg","highlights":["Cross the curved Liberty Bridge over the Reedy River falls","Let little ones loose at The Children's Museum of the Upstate","Bike the shaded Swamp Rabbit Trail as a family","Feed the giraffes at the Greenville Zoo","Hunt the nine bronze mice hidden along Main Street"],"id":"greenville-sc-downtown","interests":["family","outdoors","nature","scenic","food"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Cross the Liberty Bridge for waterfall photos, then let the kids splash in the fountains and run the lawns. Then hunt for the nine tiny bronze mice hidden along Main Street — the kids will love the scavenger hunt.","stop":"Liberty Bridge + Mice on Main hunt","time":"1:30 PM – 4:30 PM"},"day":1,"evening":{"cost":"$60–$85 for dinner (est.)","description":"Main Street is packed with family-friendly restaurants with patios. Try Southern comfort food or wood-fired pizza, then stroll back along the river.","stop":"Dinner on Main Street","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"Free (est.)","description":"Start in the heart of it all: 32 acres of gardens, fountains, and the Reedy River falls right in downtown. Cross the curved pedestrian bridge for the classic waterfall photo, then wander the riverside paths.","stop":"Falls Park on the Reedy","time":"9:00 AM – 12:00 PM"},"title":"Falls Park Day"},{"afternoon":{"cost":"Free (est.)","description":"Keep riding or turn back whenever little legs tire — the trail is flat and shaded, with ice cream stops along the way. Back downtown for a rest.","stop":"More trail time","time":"2:00 PM – 4:00 PM"},"day":2,"evening":{"cost":"$50–$75 for dinner (est.)","description":"Easy dinner back downtown, then an early night.","stop":"Dinner downtown","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"$15–$30/bike (est.)","description":"Rent bikes near Falls Park — with tag-alongs and trailers for the little ones — and pedal the Swamp Rabbit Trail along the river. Go as far as you like; even an hour out and back is a delight.","stop":"Swamp Rabbit Trail bike ride","time":"9:00 AM – 12:30 PM"},"title":"Trail Day"},{"afternoon":{"cost":"Free (est.)","description":"Souvenir shopping on Main Street and one last stroll through Falls Park before hitting the road.","stop":"Main Street + farewell stroll","time":"1:30 PM – 3:30 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"Hit the road home.","stop":"Departure","time":"4:00 PM – 5:00 PM"},"morning":{"cost":"$12/adult, $8/child (est.)","description":"Start at opening and head for the giraffe feeding deck. The zoo is compact — 2-3 hours covers everything — and the farmyard area is perfect for the under-5 crowd.","stop":"Greenville Zoo","time":"9:00 AM – 12:00 PM"},"title":"Zoo + Farewell"}],"lat":34.8526,"lng":-82.394,"overview":"Greenville is a small city with an outsized downtown: a waterfall park in the city center, a 22-mile riverside bike trail, a first-rate children's museum, and a walkable zoo. Everything is close, everything is affordable, and the whole place feels designed for families. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["The Children's Museum of the Upstate — three floors of hands-on play, $12/person (est.)","Greenville County Museum of Art — free museum with family programs, free (est.)","Model Train Station — indoor model railroad wonderland the kids will love, $10/person (est.)"],"region":"Upstate","related":["asheville-nc-mountains","charlotte-nc-city","blue-ridge-ga-mountains"],"restaurants":[{"detail":"Downtown favorite for Southern comfort food — fried chicken, pimento cheese — with a kids' menu.","name":"Soby's","price":"$$"},{"detail":"Family-friendly Italian with wood-fired pizzas kids love, right on Main Street.","name":"Trio Brick Oven Cafe","price":"$$"},{"detail":"Casual riverfront barbecue — pulled pork, ribs, and a relaxed patio the kids will love.","name":"Smoke on the Water","price":"$"}],"state":"SC","stateName":"South Carolina","tagline":"A waterfall downtown, a trail to ride, and a city made for families.","title":"Greenville, SC: Three-Day Downtown Adventure","tripType":"city adventure","imageAsset":"assets/southeast/greenville-sc-downtown/hero.jpg"},{"attractions":[{"description":"The island's most family-ready beach: free parking, outdoor showers, restrooms, a splash pad, and gentle surf on hard-packed sand that's famous for bike riding. Rent umbrellas and chairs right on the sand, and walk to the shops and cafes of Coligny Plaza for lunch.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Coligny+Beach+Park+Hilton+Head+Island+SC","name":"Coligny Beach Park","officialUrl":"https://www.hiltonheadislandsc.gov","photos":["assets/southeast/hilton-head-sc-beach/attr1-1.jpg","assets/southeast/hilton-head-sc-beach/attr1-2.jpg","assets/southeast/hilton-head-sc-beach/attr1-3.jpg","assets/southeast/hilton-head-sc-beach/attr1-4.jpg"],"price":"Free; chair rentals ~$40/day (est.)"},{"description":"A 4,000-acre wildlife refuge between the island and the mainland — alligators, roseate spoonbills, white ibis, and bald eagles along 14 miles of flat trails. Bring bikes (or rent) and binoculars; the Ibis Pond loop is the wildlife jackpot. Free and open sunrise to sunset.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Pinckney+Island+National+Wildlife+Refuge+SC","name":"Pinckney Island National Wildlife Refuge","officialUrl":"https://www.fws.gov/refuge/pinckney-island","photos":["assets/southeast/hilton-head-sc-beach/attr2-1.jpg","assets/southeast/hilton-head-sc-beach/attr2-2.jpg","assets/southeast/hilton-head-sc-beach/attr2-3.jpg","assets/southeast/hilton-head-sc-beach/attr2-4.jpg"],"price":"Free (est.)"},{"description":"The island's candy-striped icon at Harbour Town Yacht Basin. Climb 114 steps for panoramic views, stop at each landing's mini-museum of island history, and let the kids pick a souvenir in the shop at the top. The playground and marina around it make a full afternoon.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Harbour+Town+Lighthouse+Hilton+Head+Island+SC","name":"Harbour Town Lighthouse","officialUrl":"https://www.harbourtownlighthouse.com","photos":["assets/southeast/hilton-head-sc-beach/attr3-1.jpg","assets/southeast/hilton-head-sc-beach/attr3-2.jpg","assets/southeast/hilton-head-sc-beach/attr3-3.jpg","assets/southeast/hilton-head-sc-beach/attr3-4.jpg"],"price":"$8/adult, $5/child (est.)"},{"description":"Ninety-minute narrated cruises from Harbour Town where Atlantic bottlenose dolphins ride the bow wake — sightings are near-guaranteed. The sunset cruise is the one to book; kids get a kick out of the captain's stories and the onboard snack bar.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Vagabond+Cruise+Hilton+Head+Island+SC","name":"Vagabond Cruise Dolphin Tour","officialUrl":"https://www.vagabondcruise.com","photos":["assets/southeast/hilton-head-sc-beach/attr4-1.jpg","assets/southeast/hilton-head-sc-beach/attr4-2.jpg","assets/southeast/hilton-head-sc-beach/attr4-3.jpg","assets/southeast/hilton-head-sc-beach/attr4-4.jpg"],"price":"$45/adult, $25/child (est.)"}],"bestSeason":"April–October","budget":1550,"budgetNote":"Estimate for 2 adults + 2 kids over 4 days; lodging and gas not included.","days":4,"destination":"Hilton Head Island, SC","driveNotes":"Hilton Head is about 45 minutes from Savannah/Hilton Head International Airport and 4 hours from Charlotte via I-77 and US-278. The island is 12 miles long — rent bikes (many rentals deliver) and you'll barely need the car. Parking at beach parks is easy and mostly free; Sea Pines (Harbour Town) has a $9/car gate fee (est.).","familyFriendly":"Best for ages 3+. The beach, lighthouse climb (114 steps — toddlers ride up in arms), and dolphin cruises are all kid-friendly; the island is famously bikeable and stroller-friendly.","heroPhoto":"assets/southeast/hilton-head-sc-beach/hero.jpg","highlights":["Ride bikes on the hard-packed sand at Coligny Beach Park","Spot alligators and spoonbills at Pinckney Island refuge","Climb the candy-striped Harbour Town Lighthouse","Watch dolphins ride the bow wake on a sunset cruise","Kayak the calm creeks of the salt marsh"],"id":"hilton-head-sc-beach","interests":["family","beaches","outdoors","nature","scenic"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Claim your spot on the sand, splash in the gentle surf, and let the kids loose on the splash pad. Bike rental shops are right across the street if you want wheels.","stop":"Coligny Beach Park","time":"2:00 PM – 5:30 PM"},"day":1,"evening":{"cost":"$60–$85 for dinner (est.)","description":"Walk to Coligny Plaza for dinner — plenty of casual family spots with outdoor seating — then browse the shops.","stop":"Dinner at Coligny Plaza","time":"6:00 PM – 8:30 PM"},"morning":{"cost":"Free (est.)","description":"Arrive, settle into your rental, and get the lay of the land. The island is made for bikes — pick up rentals (many deliver) and take a shakedown ride.","stop":"Arrival + bike rentals","time":"10:00 AM – 12:00 PM"},"title":"Beach Arrival"},{"afternoon":{"cost":"$8/adult, $5/child (est.)","description":"Climb the 114 steps of the candy-striped lighthouse, stopping at the history exhibits on each landing. The marina, playground, and shops around Harbour Town fill the rest of the afternoon.","stop":"Harbour Town Lighthouse","time":"1:30 PM – 4:30 PM"},"day":2,"evening":{"cost":"$45/adult, $25/child (est.)","description":"Board the sunset dolphin cruise — bottlenose dolphins riding the bow wake as the sky turns gold. Book ahead; evening cruises sell out in summer.","stop":"Vagabond sunset dolphin cruise","time":"6:00 PM – 7:45 PM"},"morning":{"cost":"Free (est.)","description":"A full beach morning at Coligny: swim, build castles, ride bikes on the hard-packed sand at low tide. Pack a cooler and stay until lunch.","stop":"Beach morning","time":"9:00 AM – 12:30 PM"},"title":"Lighthouse + Dolphins"},{"afternoon":{"cost":"Free (est.)","description":"Head back to the beach for a lazy afternoon, or try a family kayak tour through the salt marsh creeks — calm water, great for beginners.","stop":"Beach or kayak tour","time":"1:30 PM – 4:30 PM"},"day":3,"evening":{"cost":"$$","description":"Dinner at a Lowcountry seafood spot, then a sunset walk on the beach.","stop":"Dinner + sunset beach walk","time":"6:00 PM – 8:00 PM"},"morning":{"cost":"Free (est.)","description":"Bike the 14 miles of flat trails at this 4,000-acre refuge. Alligators sun on the banks, spoonbills wade in the ponds, and the Ibis Pond loop is the wildlife jackpot. Bring binoculars.","stop":"Pinckney Island National Wildlife Refuge","time":"8:30 AM – 12:00 PM"},"title":"Wildlife Refuge Day"},{"afternoon":{"cost":"Free (est.)","description":"One last swim, souvenir shopping at Coligny Plaza, and the drive home.","stop":"Farewell beach + departure","time":"12:00 PM – 3:00 PM"},"day":4,"evening":{"cost":"Free (est.)","description":"Depart the island.","stop":"Departure","time":"4:00 PM – 6:00 PM"},"morning":{"cost":"Free (est.)","description":"Sunrise walk on the beach — dolphins often feed close to shore in the morning — then a pancake breakfast before checkout.","stop":"Sunrise beach walk","time":"7:30 AM – 10:30 AM"},"title":"Farewell to the Island"}],"lat":32.2163,"lng":-80.7526,"overview":"Hilton Head is the Lowcountry's family island: 12 miles of bikeable beach, a wildlife refuge full of alligators and spoonbills, a candy-striped lighthouse, and dolphin cruises at sunset. It's relaxed, safe, and easy — the kind of place where the biggest decision is beach or pool. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["The Sandbox Children's Museum — hands-on play museum on the island, $10/person (est.)","Coastal Discovery Museum — Lowcountry history and live animals, $12/adult (est.)","Island Playground + Harbour Town shops — covered play areas and souvenir browsing, free (est.)"],"region":"Lowcountry","related":["charleston-sc-historic","myrtle-beach-sc-coastal","savannah-ga-city"],"restaurants":[{"detail":"Beloved local breakfast spot — huge pancakes and crab cake benedicts — with a kids' menu and island vibe.","name":"Palmetto Bay Sunrise Cafe","price":"$$"},{"detail":"Waterfront Lowcountry seafood with sunset views over the marsh; kid-friendly and relaxed.","name":"Hudson's Seafood House on the Docks","price":"$$"},{"detail":"Casual island pizza and pasta in Harbour Town — easy, quick, and always a kid win.","name":"Giuseppi's Pizza and Pasta","price":"$"}],"state":"SC","stateName":"South Carolina","tagline":"Bikeable beaches, dolphin cruises, and Lowcountry wildlife.","title":"Hilton Head Island, SC: Four-Day Beach Escape","tripType":"beach vacation","imageAsset":"assets/southeast/hilton-head-sc-beach/hero.jpg"},{"attractions":[{"description":"One of the country's best zoos, spread across both banks of the Congaree River: gorillas, koalas, elephants, and a sea lion feeding show. Cross the river on the pedestrian bridge to the botanical garden side with its waterfall and splash areas. Plan a full day — it's big and it's excellent.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Riverbanks+Zoo+and+Garden+Columbia+SC","name":"Riverbanks Zoo and Garden","officialUrl":"https://www.riverbanks.org","photos":["assets/southeast/columbia-sc-capital/attr1-1.jpg","assets/southeast/columbia-sc-capital/attr1-2.jpg","assets/southeast/columbia-sc-capital/attr1-3.jpg","assets/southeast/columbia-sc-capital/attr1-4.jpg"],"price":"$25/adult, $20/child (est.)"},{"description":"A stunning granite-and-marble capitol with free guided tours and grounds full of monuments and gardens the kids can roam. The bronze stars marking Sherman's cannonball strikes are a hit with history-loving kids. Tours run weekdays — check the schedule before you go.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=South+Carolina+State+House+Columbia+SC","name":"South Carolina State House","officialUrl":"https://www.scstatehouse.gov","photos":["assets/southeast/columbia-sc-capital/attr2-1.jpg","assets/southeast/columbia-sc-capital/attr2-2.jpg","assets/southeast/columbia-sc-capital/attr2-3.jpg","assets/southeast/columbia-sc-capital/attr2-4.jpg"],"price":"Free; tours free (est.)"},{"description":"The South's largest children's museum, anchored by EDDIE — a 40-foot-tall statue kids can climb through. Three floors of hands-on exhibits, a flight simulator, and a fire truck to explore. A full half-day for the under-10 crowd, easy.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=EdVenture+Children%27s+Museum+Columbia+SC","name":"EdVenture Children's Museum","officialUrl":"https://www.edventure.org","photos":["assets/southeast/columbia-sc-capital/attr3-1.jpg","assets/southeast/columbia-sc-capital/attr3-2.jpg","assets/southeast/columbia-sc-capital/attr3-3.jpg","assets/southeast/columbia-sc-capital/attr3-4.jpg"],"price":"$15/person ages 2+ (est.)"},{"description":"The largest intact expanse of old-growth bottomland hardwood forest in the Southeast, 30 minutes from downtown. The 2.4-mile elevated boardwalk loop is flat, stroller-friendly, and magical — towering cypresses, birds, and the occasional river otter. Free entry; bring bug spray in summer.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Congaree+National+Park+SC","name":"Congaree National Park","officialUrl":"https://www.nps.gov/cong","photos":["assets/southeast/columbia-sc-capital/attr4-1.jpg","assets/southeast/columbia-sc-capital/attr4-2.jpg","assets/southeast/columbia-sc-capital/attr4-3.jpg","assets/southeast/columbia-sc-capital/attr4-4.jpg"],"price":"Free (est.)"}],"bestSeason":"March–June, September–November","budget":850,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days; lodging and gas not included.","days":3,"destination":"Columbia, SC","driveNotes":"Columbia sits at the junction of I-20 and I-26, about 1.5 hours from Charlotte, 2 from Charleston, and 3.5 from Atlanta — an easy drive from anywhere in the region. The city is car-friendly with easy parking everywhere. Congaree National Park is 30 minutes southeast; everything else is within 15 minutes of downtown.","familyFriendly":"Best for ages 3+. The zoo, EdVenture, and the State House grounds are toddler-friendly; the Congaree boardwalk is flat and stroller-friendly but bring bug spray.","heroPhoto":"assets/southeast/columbia-sc-capital/hero.jpg","highlights":["Spend a full day at the top-ranked Riverbanks Zoo","Tour the grand South Carolina State House — free","Climb through 40-foot EDDIE at EdVenture","Walk the elevated boardwalk through ancient Congaree forest","Picnic on the State House grounds among the monuments"],"id":"columbia-sc-capital","interests":["family","museums","outdoors","nature","historical-sites"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Cross the pedestrian bridge to the botanical garden side — waterfall, walled garden, and splash fountains the kids will love on a warm day.","stop":"Riverbanks botanical garden side","time":"1:30 PM – 4:30 PM"},"day":1,"evening":{"cost":"$50–$75 for dinner (est.)","description":"Dinner in the Vista arts district, then an early night.","stop":"Dinner in the Vista","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"$25/adult, $20/child (est.)","description":"Arrive at opening and head for the gorilla and elephant habitats, then the sea lion feeding. The zoo is big — rent a wagon at the gate if little legs tire.","stop":"Riverbanks Zoo and Garden","time":"9:00 AM – 1:00 PM"},"title":"Zoo Day"},{"afternoon":{"cost":"$15/person (est.)","description":"Three floors of hands-on exhibits and the 40-foot EDDIE statue to climb through. Plan 3 hours — the under-8 crowd won't want to leave.","stop":"EdVenture Children's Museum","time":"1:00 PM – 4:00 PM"},"day":2,"evening":{"cost":"$60–$85 for dinner (est.)","description":"Dinner downtown, then a stroll along the riverwalk at sunset.","stop":"Dinner + riverwalk","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"Free (est.)","description":"Free guided tour of the granite capitol (weekdays), then roam the monument-filled grounds. Kids love finding the bronze stars marking cannonball strikes.","stop":"South Carolina State House","time":"9:30 AM – 12:00 PM"},"title":"Capital Day"},{"afternoon":{"cost":"Free (est.)","description":"Souvenir stop downtown and the drive home.","stop":"Departure","time":"1:30 PM – 3:00 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"Hit the road.","stop":"Departure","time":"3:00 PM – 5:00 PM"},"morning":{"cost":"Free (est.)","description":"Drive 30 minutes to the national park and walk the 2.4-mile elevated boardwalk loop through ancient cypress forest. Flat, stroller-friendly, and otherworldly. Bring bug spray.","stop":"Congaree National Park","time":"9:00 AM – 12:30 PM"},"title":"Forest Day"}],"lat":34.0007,"lng":-81.0348,"overview":"Columbia is the affordable family capital of South Carolina: a top-ranked zoo and botanical garden, a grand free-to-tour State House, the South's largest children's museum, and an ancient national park forest 30 minutes away. Everything is close, parking is easy, and your wallet will thank you. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["South Carolina State Museum — four floors of art, history, and science, $12/adult (est.)","Columbia Museum of Art — family programs and free admission days, $10/adult (est.)","Frankie's Fun Park indoor arcade — rides, games, and mini golf under cover, prices vary (est.)"],"region":"Midlands","related":["raleigh-durham-nc-triangle","charlotte-nc-city","atlanta-ga-city"],"restaurants":[{"detail":"Upscale-but-welcoming Southern bistro in the Vista with a kids' menu and famous tomato pie.","name":"Motor Supply Co. Bistro","price":"$$"},{"detail":"Beloved local meat-and-three chain — fried chicken, veggies, and sweet tea; very family-friendly.","name":"Lizard's Thicket","price":"$"},{"detail":"Casual New Southern cafe famous for its shrimp and grits and friendly service.","name":"Mr. Friendly's New Southern Cafe","price":"$$"}],"state":"SC","stateName":"South Carolina","tagline":"A top-ranked zoo, a grand capitol, and an ancient forest nearby.","title":"Columbia, SC: Three-Day Capital Getaway","tripType":"capital getaway","imageAsset":"assets/southeast/columbia-sc-capital/hero.jpg"},{"attractions":[{"description":"Savannah's 30-acre crown jewel: the famous 1858 fountain, shady live oaks dripping with Spanish moss, a fragrant garden, and playgrounds. Pack a picnic, let the kids run the lawns, and snap the family photo at the fountain. Free and open daily.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Forsyth+Park+Savannah+GA","name":"Forsyth Park","officialUrl":"https://www.savannahga.gov/844/Forsyth-Park","photos":["assets/southeast/savannah-ga-city/attr1-1.jpg","assets/southeast/savannah-ga-city/attr1-2.jpg","assets/southeast/savannah-ga-city/attr1-3.jpg","assets/southeast/savannah-ga-city/attr1-4.jpg"],"price":"Free (est.)"},{"description":"The most photographed mile in Georgia: a 1.5-mile avenue of 400 live oaks draped in Spanish moss leading to a colonial plantation ruin and museum. Walk or drive the avenue slowly — kids love counting the trees — then explore the tabby ruins and nature trails.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Wormsloe+Historic+Site+Savannah+GA","name":"Wormsloe Historic Site","officialUrl":"https://www.wormsloe.org","photos":["assets/southeast/savannah-ga-city/attr2-1.jpg","assets/southeast/savannah-ga-city/attr2-2.jpg","assets/southeast/savannah-ga-city/attr2-3.jpg","assets/southeast/savannah-ga-city/attr2-4.jpg"],"price":"$10/adult, $4.50/child (est.)"},{"description":"Nine blocks of cobblestone streets along the Savannah River lined with old cotton warehouses turned shops, candy stores, and restaurants. Ride the free ferry across the river and back for skyline views, watch the giant container ships pass, and grab pralines from River Street Sweets.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=River+Street+Savannah+GA","name":"Savannah Riverfront","officialUrl":"https://www.visitsavannah.com","photos":["assets/southeast/savannah-ga-city/attr3-1.jpg","assets/southeast/savannah-ga-city/attr3-2.jpg","assets/southeast/savannah-ga-city/attr3-3.jpg","assets/southeast/savannah-ga-city/attr3-4.jpg"],"price":"Free; ferry free (est.)"},{"description":"Savannah's beach, 20 minutes east: wide sandy shores, the climbable 178-step Tybee Island Light Station, and a laid-back pier. North Beach is quieter for families; the marine science center's touch tanks are a rainy-day backup. Low-key and affordable.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Tybee+Island+GA","name":"Tybee Island","officialUrl":"https://www.tybeelighthouse.org","photos":["assets/southeast/savannah-ga-city/attr4-1.jpg","assets/southeast/savannah-ga-city/attr4-2.jpg","assets/southeast/savannah-ga-city/attr4-3.jpg","assets/southeast/savannah-ga-city/attr4-4.jpg"],"price":"Beach free; lighthouse $12/adult, $10/child (est.)"}],"bestSeason":"March–June, September–November","budget":1250,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days; lodging and gas not included.","days":3,"destination":"Savannah, GA","driveNotes":"Savannah is 2 hours from Charleston, 4 from Atlanta, and 4.5 from Charlotte, mostly on I-16 and I-95 — an easy drive. The historic district is flat and wonderfully walkable; park in a garage (about $2/hr, est.) and leave the car. Tybee Island is 20 minutes east via US-80, an easy half-day trip.","familyFriendly":"Best for ages 3+. Forsyth Park, the riverfront, and Tybee's beaches are toddler-friendly; Wormsloe's oak avenue is a gentle walk but bring a carrier for the trails.","heroPhoto":"assets/southeast/savannah-ga-city/hero.jpg","highlights":["Pose at the famous fountain in Forsyth Park","Drive the mile-long oak avenue at Wormsloe","Ride the free ferry along the Savannah River","Climb the 178 steps of the Tybee Island lighthouse","Snack your way down cobblestone River Street"],"id":"savannah-ga-city","interests":["family","historical-sites","beaches","food","scenic"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Stroll the oak-shaded squares toward the river, ending at cobblestone River Street. Watch the container ships, ride the free ferry across and back, and grab pralines.","stop":"Historic squares + River Street","time":"2:00 PM – 5:30 PM"},"day":1,"evening":{"cost":"$60–$85 for dinner (est.)","description":"Dinner in the historic district — Southern comfort food or fresh seafood — then a ghost-tour-free evening stroll (save the spooky stuff for when they're older).","stop":"Dinner downtown","time":"6:00 PM – 8:30 PM"},"morning":{"cost":"Free (est.)","description":"Start at Savannah's most beautiful park: the 1858 fountain, live oaks with Spanish moss, playgrounds, and room to run. Pack a picnic or grab coffee and pastries nearby.","stop":"Forsyth Park","time":"9:00 AM – 12:00 PM"},"title":"Park + River Day"},{"afternoon":{"cost":"Free (est.)","description":"Back in town for a trolley tour or a wander through the City Market, then ice cream on Broughton Street.","stop":"City Market + Broughton Street","time":"2:00 PM – 4:30 PM"},"day":2,"evening":{"cost":"$55–$80 for dinner (est.)","description":"Easy dinner back in the historic district.","stop":"Dinner","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"$10/adult, $4.50/child (est.)","description":"Drive the breathtaking 1.5-mile oak avenue slowly, then explore the colonial tabby ruins, museum, and nature trails. Go early — the avenue is magical in morning light.","stop":"Wormsloe Historic Site","time":"9:00 AM – 12:00 PM"},"title":"Wormsloe Day"},{"afternoon":{"cost":"$12/adult, $10/child (est.)","description":"Climb the 178 steps of Georgia's oldest and tallest lighthouse for panoramic views, then explore the keeper's cottages and museum.","stop":"Tybee Island Light Station","time":"1:00 PM – 3:00 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"Drive home via I-16.","stop":"Departure","time":"4:00 PM – 6:00 PM"},"morning":{"cost":"Free (est.)","description":"Twenty minutes east to Savannah's beach: wide sand, gentle surf, and sea oats. North Beach is the quiet family pick; the pier area has more action.","stop":"Tybee Island beach","time":"9:00 AM – 12:30 PM"},"title":"Beach Day"}],"lat":32.0809,"lng":-81.0918,"overview":"Savannah is storybook beautiful: moss-draped oaks, 24 shady squares, a famous park fountain, and a beach 20 minutes away. It's compact, walkable, and free to wander — with a mile-long oak avenue and a climbable lighthouse to anchor the days. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Telfair Children's Art Museum (Jepson Center) — hands-on art play, $25/adult (est.)","Savannah Children's Museum — outdoor/indoor play museum, $12/person (est.)","Tybee Island Marine Science Center — touch tanks and turtle talks, $10/adult (est.)"],"region":"Coastal Georgia","related":["charleston-sc-historic","hilton-head-sc-beach","jekyll-island-ga-coastal"],"restaurants":[{"detail":"Iconic Southern restaurant in a historic mansion — fried chicken, she-crab soup — beloved by families.","name":"The Olde Pink House","price":"$$"},{"detail":"Beloved local spot for shrimp and grits, fried green tomatoes, and Southern classics.","name":"The Grey","price":"$$"},{"detail":"Casual, kid-approved spot for wood-fired pizza and gelato near the river.","name":"Vinnie Van Go-Go's","price":"$"}],"state":"GA","stateName":"Georgia","tagline":"Moss-draped oaks, a famous fountain, and a beach 20 minutes away.","title":"Savannah, GA: Three-Day Southern Escape","tripType":"city adventure","imageAsset":"assets/southeast/savannah-ga-city/hero.jpg"},{"attractions":[{"description":"One of the world's largest aquariums, home to whale sharks, manta rays, beluga whales, and sea otters. The Ocean Voyager gallery's tunnel and giant viewing window leave kids speechless. Plan 3-4 hours; buy timed tickets online to skip lines.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Georgia+Aquarium+Atlanta+GA","name":"Georgia Aquarium","officialUrl":"https://www.georgiaaquarium.org","photos":["assets/southeast/atlanta-ga-city/attr1-1.jpg","assets/southeast/atlanta-ga-city/attr1-2.jpg","assets/southeast/atlanta-ga-city/attr1-3.jpg","assets/southeast/atlanta-ga-city/attr1-4.jpg"],"price":"$39.99/adult, $32.99/child (est.)"},{"description":"Right next door to the aquarium: a museum celebrating the world's most famous drink, from the secret formula vault to the tasting room with 100+ international flavors — the kids' favorite part. The 4-D theater is a bonus.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=World+of+Coca-Cola+Atlanta+GA","name":"World of Coca-Cola","officialUrl":"https://www.worldofcoca-cola.com","photos":["assets/southeast/atlanta-ga-city/attr2-1.jpg","assets/southeast/atlanta-ga-city/attr2-2.jpg","assets/southeast/atlanta-ga-city/attr2-3.jpg","assets/southeast/atlanta-ga-city/attr2-4.jpg"],"price":"$21/adult, $17/child (est.)"},{"description":"A standout zoo in Grant Park with one of the nation's premier gorilla habitats, giant pandas (a rotating loan), African savanna elephants, and a great train ride for little legs. Pair with the neighboring Cyclorama history experience if time allows.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Zoo+Atlanta+Atlanta+GA","name":"Zoo Atlanta","officialUrl":"https://www.zooatlanta.org","photos":["assets/southeast/atlanta-ga-city/attr3-1.jpg","assets/southeast/atlanta-ga-city/attr3-2.jpg","assets/southeast/atlanta-ga-city/attr3-3.jpg","assets/southeast/atlanta-ga-city/attr3-4.jpg"],"price":"$25.99/adult, $21.99/child (est.)"},{"description":"Designed for ages 0-8: a climbing structure, water play, pretend grocery store, and daily programs. Perfect half-day anchor for toddlers and preschoolers, especially on hot or rainy afternoons.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Children%27s+Museum+of+Atlanta+Atlanta+GA","name":"Children's Museum of Atlanta","officialUrl":"https://www.childrensmuseumatlanta.org","photos":["assets/southeast/atlanta-ga-city/attr4-1.jpg","assets/southeast/atlanta-ga-city/attr4-2.jpg","assets/southeast/atlanta-ga-city/attr4-3.jpg","assets/southeast/atlanta-ga-city/attr4-4.jpg"],"price":"$19.95/person (est.)"}],"bestSeason":"March–May, September–November","budget":1700,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days; lodging and gas not included.","days":3,"destination":"Atlanta, GA","driveNotes":"Atlanta sits at the crossroads of I-75, I-85, and I-20: 2 hours from Chattanooga, 4 from Charlotte, 4.5 from Birmingham. Traffic on the Downtown Connector is legendary — avoid rush hours (7-9 AM, 4-7 PM). The aquarium and World of Coca-Cola share a parking garage at Pemberton Place (about $18/day, est.); MARTA's Peachtree Center station reaches downtown sights car-free.","familyFriendly":"Best for ages 3+. The aquarium, zoo, and children's museum all shine for toddlers and up; the World of Coca-Cola tasting room is a hit with elementary-age kids. Downtown is very stroller-friendly.","heroPhoto":"assets/southeast/atlanta-ga-city/hero.jpg","highlights":["Stand under whale sharks at the Georgia Aquarium","Taste 100+ sodas from around the world","Watch the gorilla troops at Zoo Atlanta","Climb and splash at the Children's Museum","Ride the SkyView Ferris wheel at dusk"],"id":"atlanta-ga-city","interests":["family","museums","food","amusement-parks","nature"],"itinerary":[{"afternoon":{"cost":"$21/adult, $17/child (est.)","description":"Walk next door for the Coke story: the vault, the bottling line, and the tasting room where kids vote on their favorite international flavors. 2 hours is plenty.","stop":"World of Coca-Cola","time":"1:30 PM – 4:00 PM"},"day":1,"evening":{"cost":"$30–$45 for the ride (est.)","description":"Dinner downtown, then a ride on the 20-story SkyView Ferris wheel for glittering night views — air-conditioned gondolas the kids will love.","stop":"Dinner + SkyView Atlanta","time":"5:30 PM – 8:30 PM"},"morning":{"cost":"$39.99/adult, $32.99/child (est.)","description":"Arrive at opening for the Ocean Voyager tunnel and whale sharks before crowds build. Budget 3-4 hours; the sea otter pups and dolphin show are musts.","stop":"Georgia Aquarium","time":"9:30 AM – 1:00 PM"},"title":"Aquarium + Coke Day"},{"afternoon":{"cost":"Free (est.)","description":"Picnic or playground time at Piedmont Park's Noguchi Playscapes — Atlanta's best big-city park, with skyline views.","stop":"Piedmont Park","time":"1:30 PM – 4:00 PM"},"day":2,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Dinner in Midtown or Virginia-Highland.","stop":"Dinner","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"$19.95/person (est.)","description":"A hands-on morning built for little ones: climbing, water tables, and pretend play zones. Arrive early for the quietest hour.","stop":"Children's Museum of Atlanta","time":"10:00 AM – 12:30 PM"},"title":"Museum + Park Day"},{"afternoon":{"cost":"Free (est.)","description":"Grab lunch near the zoo, then drive home.","stop":"Lunch + departure","time":"1:30 PM – 3:00 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"Arrive home and unpack the souvenirs.","stop":"Home","time":"5:00 PM – 7:00 PM"},"morning":{"cost":"$25.99/adult, $21.99/child (est.)","description":"Head to Grant Park for the gorilla troops, elephants, and the narrated train ride. The Ford African Rain Forest is the centerpiece — go before the midday heat.","stop":"Zoo Atlanta","time":"9:30 AM – 1:00 PM"},"title":"Zoo Day"}],"lat":33.749,"lng":-84.388,"overview":"Atlanta packs a big-city punch for families: one of the world's great aquariums, the fizzy fun of the World of Coca-Cola, a top-tier zoo, and a museum built just for little kids. Base downtown and most big sights are walkable or a short MARTA hop. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Georgia Aquarium (already in the plan — stretch it to a full day)","Center for Civil and Human Rights — powerful, best for ages 8+","Fernbank Museum of Natural History — dinosaurs and WildWoods trails, $22/adult (est.)"],"region":"Metro Atlanta","related":["charlotte-nc-city","columbia-sc-capital","athens-ga-city"],"restaurants":[{"detail":"Beloved meat-and-three serving Southern classics cafeteria-style since 1947 — kids love picking their own sides.","name":"Mary Mac's Tea Room","price":"$$"},{"detail":"Classic Atlanta diner open 24/7, famous for burgers and people-watching — a fun late-night stop.","name":"The Varsity","price":"$"},{"detail":"Family-friendly Italian in Virginia-Highland with a great patio and a menu kids actually eat.","name":"La Tavola","price":"$$"}],"state":"GA","stateName":"Georgia","tagline":"Whale sharks, fizzy history, and a zoo full of gorillas.","title":"Atlanta, GA: Three-Day Big-City Family Trip","tripType":"city adventure","imageAsset":"assets/southeast/atlanta-ga-city/hero.jpg"},{"attractions":[{"description":"Jekyll's famous boneyard beach: gnarled, bleached driftwood trees scattered across the sand, looking like a natural sculpture garden. Kids climb, pose, and explore at low tide. Go early morning or golden hour — and wear shoes, the wood is rough.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Driftwood+Beach+Jekyll+Island+GA","name":"Driftwood Beach","officialUrl":"https://www.jekyllisland.com","photos":["assets/southeast/jekyll-island-ga-coastal/attr1-1.jpg","assets/southeast/jekyll-island-ga-coastal/attr1-2.jpg","assets/southeast/jekyll-island-ga-coastal/attr1-3.jpg","assets/southeast/jekyll-island-ga-coastal/attr1-4.jpg"],"price":"Free; $10 island parking pass (est.)"},{"description":"Georgia's only sea turtle education and rehabilitation center, set in a former power plant. See recovering turtles in tanks, watch feeding sessions, and learn how the center nests and tracks wild turtles. Small but heartfelt — plan 1-2 hours.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Georgia+Sea+Turtle+Center+Jekyll+Island+GA","name":"Georgia Sea Turtle Center","officialUrl":"https://www.georgiaseaturtlecenter.org","photos":["assets/southeast/jekyll-island-ga-coastal/attr2-1.jpg","assets/southeast/jekyll-island-ga-coastal/attr2-2.jpg","assets/southeast/jekyll-island-ga-coastal/attr2-3.jpg","assets/southeast/jekyll-island-ga-coastal/attr2-4.jpg"],"price":"$11/adult, $8/child (est.)"},{"description":"Jekyll's history museum covers 3,500 years — from Native Americans to the Gilded Age Millionaires' Club that once owned the island as a private retreat. Interactive exhibits and a short film; pair with a tram tour of the historic district cottages.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mosaic+Jekyll+Island+Museum+Jekyll+Island+GA","name":"Mosaic, Jekyll Island Museum","officialUrl":"https://www.jekyllisland.com","photos":["assets/southeast/jekyll-island-ga-coastal/attr3-1.jpg","assets/southeast/jekyll-island-ga-coastal/attr3-2.jpg","assets/southeast/jekyll-island-ga-coastal/attr3-3.jpg","assets/southeast/jekyll-island-ga-coastal/attr3-4.jpg"],"price":"$12/adult, $7/child (est.)"},{"description":"The island's water park: slides, a lazy river, a wave pool, and a dedicated splash zone for little kids. A perfect hot-afternoon escape from May through September. Arrive at opening for the shortest lines.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Summer+Waves+Water+Park+Jekyll+Island+GA","name":"Summer Waves Water Park","officialUrl":"https://www.summerwaves.com","photos":["assets/southeast/jekyll-island-ga-coastal/attr4-1.jpg","assets/southeast/jekyll-island-ga-coastal/attr4-2.jpg","assets/southeast/jekyll-island-ga-coastal/attr4-3.jpg","assets/southeast/jekyll-island-ga-coastal/attr4-4.jpg"],"price":"$39.99/adult, $34.99/child (est.)"}],"bestSeason":"April–June, September–October","budget":1350,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days; lodging and gas not included.","days":3,"destination":"Jekyll Island, GA","driveNotes":"Jekyll Island is off coastal Georgia via the Jekyll Island Causeway — about 1.5 hours south of Savannah on I-95, and 4.5 hours from Atlanta. You pay a parking pass at the gate (about $10/day, est.). The island is flat and bike-friendly — rent bikes and leave the car; 20+ miles of paved trails connect all sights. Summer Waves runs May–September only (est.).","familyFriendly":"Best for ages 3+. Driftwood Beach and the sea turtle center are hits with toddlers (carriers for the sand); Summer Waves has a dedicated kiddie zone. The island is quiet, safe, and very stroller/bike friendly.","heroPhoto":"assets/southeast/jekyll-island-ga-coastal/hero.jpg","highlights":["Explore the surreal driftwood forest at Driftwood Beach","Meet recovering sea turtles at the rescue center","Ride slides and float the lazy river at Summer Waves","Bike the island's 20+ miles of flat trails","Tour the Gilded Age Millionaires' cottages"],"id":"jekyll-island-ga-coastal","interests":["family","beaches","nature","amusement-parks","scenic"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Head to the island's best swimming beach: calm water, lifeguards in season, and a playground. Build sandcastles, then walk the fishing pier.","stop":"Great Dunes Beach","time":"2:00 PM – 5:00 PM"},"day":1,"evening":{"cost":"$55–$80 for dinner (est.)","description":"Casual seafood dinner on the island, then sunset back at Driftwood Beach — the golden-hour light on the bleached wood is unforgettable.","stop":"Dinner + Driftwood Beach sunset","time":"6:00 PM – 8:30 PM"},"morning":{"cost":"Free (est.)","description":"Arrive via the causeway, grab your parking pass, and head straight to the island's most magical spot: gnarled driftwood scattered across the sand like sculptures. Low tide is best for exploring.","stop":"Driftwood Beach","time":"9:30 AM – 12:00 PM"},"title":"Arrival + Driftwood Day"},{"afternoon":{"cost":"$12/adult, $7/child (est.)","description":"The island's story — from Native American shell mounds to the Gilded Age millionaires — in interactive exhibits. Pair with a tram tour of the historic cottages if energy allows.","stop":"Mosaic Museum","time":"2:00 PM – 4:30 PM"},"day":2,"evening":{"cost":"$50–$75 for dinner (est.)","description":"Dinner, then a family bike ride at dusk — the island is flat, quiet, and made for it.","stop":"Dinner + evening bike ride","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"$11/adult, $8/child (est.)","description":"Meet the recovering sea turtles in their tanks and catch a feeding session. Small, heartfelt, and perfect for animal-loving kids — plan 1-2 hours.","stop":"Georgia Sea Turtle Center","time":"10:00 AM – 12:00 PM"},"title":"Turtles + History Day"},{"afternoon":{"cost":"Free (est.)","description":"Grab lunch, then drive home via I-95.","stop":"Lunch + departure","time":"1:30 PM – 3:00 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"Home and unpack.","stop":"Home","time":"5:00 PM – 7:00 PM"},"morning":{"cost":"$39.99/adult, $34.99/child (est.)","description":"Slides, lazy river, and wave pool — arrive at opening and claim chairs near the kiddie splash zone. Sunscreen and water shoes are essential.","stop":"Summer Waves Water Park","time":"10:00 AM – 1:00 PM"},"title":"Water Park Day"}],"lat":31.1357,"lng":-81.4198,"overview":"Jekyll Island is Georgia's quiet barrier-island gem: a boneyard beach of sculptural driftwood, a sea turtle rescue center, a Gilded Age historic district, and a family water park — all connected by flat, shady bike trails. No high-rises, no crowds, just slow island days. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Georgia Sea Turtle Center (already in the plan — stretch the visit)","Mosaic Museum — indoor island-history exhibits","Millionaires' Village historic cottage tours from the Jekyll Island Authority"],"region":"Golden Isles","related":["savannah-ga-city","st-augustine-fl-coastal","key-west-fl-coastal"],"restaurants":[{"detail":"Waterfront Southern seafood with sunset views over the marsh — shrimp and grits, fish tacos, and live music on the deck.","name":"The Wharf","price":"$$"},{"detail":"Jekyll's only oceanfront restaurant: Baja Mexican, shrimp tacos, and the island's only oceanfront tiki bar — very family-friendly.","name":"Tortuga Jack's","price":"$"},{"detail":"Casual island favorite for shrimp baskets, burgers, and Southern seafood platters near the river.","name":"Zachry's Riverhouse","price":"$$"}],"state":"GA","stateName":"Georgia","tagline":"Driftwood beaches, sea turtles, and slow island days.","title":"Jekyll Island, GA: Three-Day Island Escape","tripType":"beach escape","imageAsset":"assets/southeast/jekyll-island-ga-coastal/hero.jpg"},{"attractions":[{"description":"A 4-hour round-trip heritage train ride from downtown Blue Ridge to the twin towns of McCaysville, GA and Copperhill, TN — right through the Ocoee River gorge. Kids wave at kayakers from open-air cars; the layover in McCaysville is perfect for ice cream and antique shops.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Blue+Ridge+Scenic+Railway+Blue+Ridge+GA","name":"Blue Ridge Scenic Railway","officialUrl":"https://www.brscenic.com","photos":["assets/southeast/blue-ridge-ga-mountains/attr1-1.jpg","assets/southeast/blue-ridge-ga-mountains/attr1-2.jpg","assets/southeast/blue-ridge-ga-mountains/attr1-3.jpg","assets/southeast/blue-ridge-ga-mountains/attr1-4.jpg"],"price":"$74/adult, $49/child (est.)"},{"description":"A 200-acre working family farm in the mountains since 1943 — apple picking in season, a market with fried pies and cider donuts, tractor rides, and a cafe. Even in winter, the bakery and market make the drive worth it. A North Georgia institution.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Mercier+Orchards+Blue+Ridge+GA","name":"Mercier Orchards","officialUrl":"https://www.mercierorchards.com","photos":["assets/southeast/blue-ridge-ga-mountains/attr2-1.jpg","assets/southeast/blue-ridge-ga-mountains/attr2-2.jpg","assets/southeast/blue-ridge-ga-mountains/attr2-3.jpg","assets/southeast/blue-ridge-ga-mountains/attr2-4.jpg"],"price":"Free entry; u-pick apples ~$18/bag (est.)"},{"description":"The tallest cascading waterfall east of the Mississippi at 729 feet, about 30 minutes from Blue Ridge. Hike the easy West Ridge trail to the top or climb the 604 steps alongside the falls — older kids love the challenge. Stunning in fall color.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Amicalola+Falls+State+Park+GA","name":"Amicalola Falls State Park","officialUrl":"https://gastateparks.org/AmicalolaFalls","photos":["assets/southeast/blue-ridge-ga-mountains/attr3-1.jpg","assets/southeast/blue-ridge-ga-mountains/attr3-2.jpg","assets/southeast/blue-ridge-ga-mountains/attr3-3.jpg","assets/southeast/blue-ridge-ga-mountains/attr3-4.jpg"],"price":"$5 parking (est.)"},{"description":"A sparkling 3,300-acre mountain lake with a sandy swimming beach, boat rentals, and calm coves for kayaking. The Lake Blue Ridge Day Use Area has picnic tables and a roped swim area — an easy, breezy afternoon.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Lake+Blue+Ridge+GA","name":"Lake Blue Ridge","officialUrl":"https://www.blueridgemountains.com","photos":["assets/southeast/blue-ridge-ga-mountains/attr4-1.jpg","assets/southeast/blue-ridge-ga-mountains/attr4-2.jpg","assets/southeast/blue-ridge-ga-mountains/attr4-3.jpg","assets/southeast/blue-ridge-ga-mountains/attr4-4.jpg"],"price":"Free (est.)"}],"bestSeason":"May–June, September–November","budget":1450,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days; lodging (cabins popular here) and gas not included.","days":3,"destination":"Blue Ridge, GA","driveNotes":"Blue Ridge is about 2 hours north of Atlanta via I-575/GA-515 through the mountains, or 3.5 hours from Chattanooga. Cell service gets spotty on the back roads — download maps offline. The train boards in downtown Blue Ridge; book tickets weeks ahead in fall. Amicalola Falls is 30 minutes south via GA-52.","familyFriendly":"Best for ages 4+. The train ride and orchards are perfect for all ages; Amicalola's staircase climb suits ages 6+ (the base view is easy for toddlers). Mountain cabins with hot tubs are a family favorite lodging pick.","heroPhoto":"assets/southeast/blue-ridge-ga-mountains/hero.jpg","highlights":["Ride the heritage train through the Ocoee River gorge","Pick apples and eat fried pies at Mercier Orchards","Stand at the base of 729-foot Amicalola Falls","Swim and kayak on Lake Blue Ridge","Wander the shops and fudge stores of downtown Blue Ridge"],"id":"blue-ridge-ga-mountains","interests":["family","outdoors","nature","scenic","food"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Stroll Main Street: fudge shops, toy stores, and the Blue Ridge Olive Oil Company tasting bar. Grab an early dinner downtown.","stop":"Downtown Blue Ridge","time":"3:00 PM – 5:30 PM"},"day":1,"evening":{"cost":"$55–$80 for dinner (est.)","description":"Farm-to-table dinner on Main Street, then back to the cabin.","stop":"Dinner downtown","time":"6:00 PM – 8:00 PM"},"morning":{"cost":"Free (est.)","description":"Arrive in the mountains and settle into your cabin. Explore downtown Blue Ridge's shops and grab lunch — the train depot area is full of kid-pleasers.","stop":"Arrival + downtown","time":"10:00 AM – 1:00 PM"},"title":"Arrival Day"},{"afternoon":{"cost":"Free entry; u-pick apples ~$18/bag (est.)","description":"Apple picking in season, tractor rides, fried pies, and cider donuts at the market. Even off-season, the bakery is worth the trip.","stop":"Mercier Orchards","time":"2:00 PM – 4:30 PM"},"day":2,"evening":{"cost":"$50–$75 for dinner (est.)","description":"Southern comfort dinner downtown, then s'mores back at the cabin.","stop":"Dinner + cabin evening","time":"6:00 PM – 8:30 PM"},"morning":{"cost":"$74/adult, $49/child (est.)","description":"Board the vintage train for the 4-hour round trip along the Toccoa River to McCaysville/Copperhill. Sit in an open-air car and pack snacks — the layover is made for ice cream.","stop":"Blue Ridge Scenic Railway","time":"10:00 AM – 2:00 PM"},"title":"Train + Orchard Day"},{"afternoon":{"cost":"Free (est.)","description":"Drive home through the mountains.","stop":"Departure","time":"2:00 PM – 4:00 PM"},"day":3,"evening":{"cost":"$0","description":"Home.","stop":"Home","time":"6:00 PM – 8:00 PM"},"morning":{"cost":"$5 parking (est.)","description":"Drive 30 minutes to Georgia's tallest waterfall. Take the easy West Ridge trail to the top viewpoint; brave kids can try the 604-step staircase beside the falls.","stop":"Amicalola Falls State Park","time":"9:00 AM – 12:30 PM"},"title":"Waterfall Day"}],"lat":34.8636,"lng":-84.3257,"overview":"Blue Ridge is North Georgia's mountain playground: a heritage train ride through the gorge, apple orchards with fried pies, the tallest waterfall east of the Mississippi, and a sparkling lake — all wrapped in small-town charm and cabin country. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Blue Ridge Mountain Arts Center — galleries and kids' art activities","Swan Drive-In Theater — one of America's last drive-ins, open seasonally","Mercier Orchards market and cafe (open year-round)"],"region":"North Georgia Mountains","related":["asheville-nc-mountains","greenville-sc-downtown","athens-ga-city"],"restaurants":[{"detail":"Upscale farm-to-table Southern cooking from a James Beard-nominated chef — the town's best table; book ahead.","name":"Harvest on Main","price":"$$$"},{"detail":"Chef-driven Southern comfort in a historic house — fried chicken, meatloaf, and the town's biggest patio.","name":"The Black Sheep","price":"$$"},{"detail":"Classic Southern comfort: fried chicken, biscuits and apple butter — a family favorite.","name":"Southern Charm","price":"$$"}],"state":"GA","stateName":"Georgia","tagline":"Train rides, waterfalls, and apple orchards in the North Georgia mountains.","title":"Blue Ridge, GA: Three-Day Mountain Escape","tripType":"mountain escape","imageAsset":"assets/southeast/blue-ridge-ga-mountains/hero.jpg"},{"attractions":[{"description":"The birthplace of public higher education in America (chartered 1785): stroll through the iconic Arch, see the UGA Chapel and Chapel Bell, and wander historic North Campus with its Greek Revival buildings. Free self-guided walking tours; Bulldog fans should peek at Sanford Stadium from the bridge.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=University+of+Georgia+Campus+Athens+GA","name":"University of Georgia Campus","officialUrl":"https://www.uga.edu","photos":["assets/southeast/athens-ga-city/attr1-1.jpg","assets/southeast/athens-ga-city/attr1-2.jpg","assets/southeast/athens-ga-city/attr1-3.jpg","assets/southeast/athens-ga-city/attr1-4.jpg"],"price":"Free (est.)"},{"description":"Georgia's official botanical garden: 313 acres of themed gardens, a conservatory with tropical plants, and five miles of nature trails. Kids love the Alice H. Richards Flower Garden and the canopy walk. Free admission; the conservatory is a lovely rainy-day stop.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=State+Botanical+Garden+of+Georgia+Athens+GA","name":"State Botanical Garden of Georgia","officialUrl":"https://botgarden.uga.edu","photos":["assets/southeast/athens-ga-city/attr2-1.jpg","assets/southeast/athens-ga-city/attr2-2.jpg","assets/southeast/athens-ga-city/attr2-3.jpg","assets/southeast/athens-ga-city/attr2-4.jpg"],"price":"Free (est.)"},{"description":"The state's official art museum on the UGA campus, free and family-friendly: American paintings, decorative arts, and rotating exhibitions. The family programs and scavenger hunts keep kids engaged; check for free Family Day events.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Georgia+Museum+of+Art+Athens+GA","name":"Georgia Museum of Art","officialUrl":"https://www.georgiamuseum.org","photos":["assets/southeast/athens-ga-city/attr3-1.jpg","assets/southeast/athens-ga-city/attr3-2.jpg","assets/southeast/athens-ga-city/attr3-3.jpg","assets/southeast/athens-ga-city/attr3-4.jpg"],"price":"Free (est.)"},{"description":"A free, county-run wildlife exhibit in Memorial Park housing black bears, owls, alligators, and other animals that can't be released into the wild. Small and shaded — a sweet 1-hour stop for little animal lovers, with a playground next door.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Bear+Hollow+Zoo+Athens+GA","name":"Bear Hollow Zoo","officialUrl":"https://www.accgov.com/bearhollow","photos":["assets/southeast/athens-ga-city/attr4-1.jpg","assets/southeast/athens-ga-city/attr4-2.jpg","assets/southeast/athens-ga-city/attr4-3.jpg","assets/southeast/athens-ga-city/attr4-4.jpg"],"price":"Free (est.)"}],"bestSeason":"March–May, September–November","budget":1150,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days; lodging and gas not included.","days":3,"destination":"Athens, GA","driveNotes":"Athens is about 1.5 hours east of Atlanta on US-78/GA-316, and 2.5 hours from Greenville, SC. Parking downtown is metered (about $1/hr, est.); the UGA campus has visitor lots on weekends. The botanical garden is 10 minutes south of downtown on Milledge Avenue. Game-day weekends (fall Saturdays) book out hotels and clog traffic — check the UGA schedule.","familyFriendly":"Best for ages 3+. Bear Hollow Zoo and the botanical garden are ideal for toddlers; the campus walk and art museum work best with elementary-age kids. Athens is a relaxed, walkable college town.","heroPhoto":"assets/southeast/athens-ga-city/hero.jpg","highlights":["Walk through the iconic UGA Arch","Explore 313 acres at the State Botanical Garden","Meet the bears at free Bear Hollow Zoo","Hunt for art at the Georgia Museum of Art","Eat your way through downtown Athens"],"id":"athens-ga-city","interests":["family","museums","food","outdoors","nature"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Self-guided stroll through the Arch, North Campus, the Chapel, and Herty Field. End at the Tate Student Center for ice cream.","stop":"UGA campus walk","time":"2:00 PM – 4:30 PM"},"day":1,"evening":{"cost":"$55–$80 for dinner (est.)","description":"Dinner downtown — Athens is a food town — then a walk past the famous music venues (Georgia Theatre, 40 Watt Club).","stop":"Dinner downtown","time":"5:30 PM – 8:00 PM"},"morning":{"cost":"Free (est.)","description":"Arrive in the Classic City and start with Bear Hollow Zoo in Memorial Park: bears, owls, and alligators that can't be released into the wild, plus the playground next door. A perfect 1-hour warm-up.","stop":"Bear Hollow Zoo","time":"10:00 AM – 12:00 PM"},"title":"Arrival + Zoo Day"},{"afternoon":{"cost":"Free (est.)","description":"Picnic among the flowers, walk the canopy boardwalk, and let the kids run the Children's Garden.","stop":"Botanical garden trails","time":"1:30 PM – 4:00 PM"},"day":2,"evening":{"cost":"$50–$75 for dinner (est.)","description":"Casual downtown dinner — Athens has great low-key spots for families.","stop":"Dinner","time":"5:30 PM – 7:30 PM"},"morning":{"cost":"Free (est.)","description":"313 acres of themed gardens and a tropical conservatory. Go early for the coolest hours; the Flower Garden is the showpiece.","stop":"State Botanical Garden of Georgia","time":"9:30 AM – 12:30 PM"},"title":"Garden Day"},{"afternoon":{"cost":"Free (est.)","description":"Drive home via GA-316/US-78.","stop":"Departure","time":"2:00 PM – 4:00 PM"},"day":3,"evening":{"cost":"$0","description":"Home.","stop":"Home","time":"6:00 PM – 8:00 PM"},"morning":{"cost":"Free (est.)","description":"The state's official art museum: American art, decorative arts, and family scavenger hunts. Check for free Family Day programs before you go.","stop":"Georgia Museum of Art","time":"10:00 AM – 12:00 PM"},"title":"Art Day"}],"lat":33.9519,"lng":-83.3576,"overview":"Athens is the Classic City: a lively college town with a gorgeous historic campus, a huge free botanical garden, a free art museum, and a free little zoo — plus one of Georgia's best food scenes. It's affordable, walkable, and easygoing, a perfect long weekend. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Georgia Museum of Art (already in the plan)","UGA Special Collections Libraries — Georgia history exhibits, free","Bear Hollow Zoo's covered exhibits + Memorial Park recreation center"],"region":"Northeast Georgia","related":["atlanta-ga-city","blue-ridge-ga-mountains","greenville-sc-downtown"],"restaurants":[{"detail":"Mediterranean-inspired downtown favorite — great for a family date-night dinner.","name":"The National","price":"$$"},{"detail":"Beloved breakfast and brunch spot — famous biscuits, skillets, and Georgia peach French toast.","name":"Mama's Boy","price":"$"},{"detail":"Iconic Athens vegetarian institution with huge portions and a fun, funky vibe — meat-eaters welcome.","name":"The Grit","price":"$"}],"state":"GA","stateName":"Georgia","tagline":"A classic college town with gardens, art, and a free zoo.","title":"Athens, GA: Three-Day Classic City Trip","tripType":"city adventure","imageAsset":"assets/southeast/athens-ga-city/hero.jpg"},{"attractions":[{"description":"The vacation kingdom itself: four theme parks led by Magic Kingdom's castle and fireworks. With little kids, plan one park per day, rope-drop at opening, and take a midday hotel break — the heat and crowds are real. Buy tickets and reserve parks online well ahead.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Walt+Disney+World+Orlando+FL","name":"Walt Disney World","officialUrl":"https://disneyworld.disney.go.com","photos":["assets/southeast/orlando-fl-city/attr1-1.jpg","assets/southeast/orlando-fl-city/attr1-2.jpg","assets/southeast/orlando-fl-city/attr1-3.jpg","assets/southeast/orlando-fl-city/attr1-4.jpg"],"price":"1-day ticket ~$109+/person (est.)"},{"description":"Two parks for bigger kids and movie fans: the Wizarding World of Harry Potter (ride the Hogwarts Express between parks), Jurassic World, and Seuss Landing for little ones. More coasters, fewer princesses — a great complement to Disney.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Universal+Orlando+Resort+Orlando+FL","name":"Universal Orlando Resort","officialUrl":"https://www.universalorlando.com","photos":["assets/southeast/orlando-fl-city/attr2-1.jpg","assets/southeast/orlando-fl-city/attr2-2.jpg","assets/southeast/orlando-fl-city/attr2-3.jpg","assets/southeast/orlando-fl-city/attr2-4.jpg"],"price":"1-day 2-park ticket ~$164+/person (est.)"},{"description":"An hour east of Orlando: NASA's visitor complex with the real Space Shuttle Atlantis, the Saturn V rocket, the Shuttle Launch Experience simulator, and bus tours to launch pads. The kids' play dome and astronaut encounters make it a full, awe-filled day.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Kennedy+Space+Center+FL","name":"Kennedy Space Center Visitor Complex","officialUrl":"https://www.kennedyspacecenter.com","photos":["assets/southeast/orlando-fl-city/attr3-1.jpg","assets/southeast/orlando-fl-city/attr3-2.jpg","assets/southeast/orlando-fl-city/attr3-3.jpg","assets/southeast/orlando-fl-city/attr3-4.jpg"],"price":"$75/adult, $65/child (est.)"},{"description":"45 minutes southwest in Winter Haven: rides, shows, and Miniland USA built for ages 2-12 — the sweet spot the big parks miss. Smaller, calmer, and cheaper, with a water park add-on for hot days. Perfect for the LEGO-obsessed.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=LEGOLAND+Florida+Winter+Haven+FL","name":"LEGOLAND Florida Resort","officialUrl":"https://florida.legoland.com","photos":["assets/southeast/orlando-fl-city/attr4-1.jpg","assets/southeast/orlando-fl-city/attr4-2.jpg","assets/southeast/orlando-fl-city/attr4-3.jpg","assets/southeast/orlando-fl-city/attr4-4.jpg"],"price":"~$99/person (est.)"}],"bestSeason":"January–April, late September–November","budget":3200,"budgetNote":"Estimate for 2 adults + 2 kids over 4 days (theme-park tickets are the big cost); lodging and gas not included.","days":4,"destination":"Orlando, FL","driveNotes":"Orlando is 3.5 hours from Tampa and 3 from Jacksonville on I-4 and the Florida Turnpike. Disney and Universal are 20 minutes apart; parking is about $30/day at the parks (est.). Kennedy Space Center is an hour east via SR-528 (toll road); LEGOLAND is 45 minutes southwest. Summer afternoons bring thunderstorms — plan indoor shows for 2-4 PM.","familyFriendly":"Best for ages 4+. Disney's Magic Kingdom is built for toddlers (rider swap for big rides); Universal skews to ages 7+; LEGOLAND is ideal for ages 2-12; Kennedy Space Center works for all ages. Midday breaks are essential in summer heat.","heroPhoto":"assets/southeast/orlando-fl-city/hero.jpg","highlights":["See the castle and fireworks at Magic Kingdom","Ride the Hogwarts Express between Universal's parks","Meet the real Space Shuttle Atlantis","Build and ride at LEGOLAND Florida","Cool off at Disney Springs in the evening"],"id":"orlando-fl-city","interests":["family","amusement-parks","museums","food","outdoors"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Midday break back at the hotel — rest, swim, recharge. The parks are hottest and busiest now.","stop":"Hotel pool break","time":"1:00 PM – 4:00 PM"},"day":1,"evening":{"cost":"Varies (est.)","description":"Back to Magic Kingdom for the afternoon parade and evening fireworks — stake out a spot on Main Street an hour early.","stop":"Magic Kingdom fireworks","time":"5:00 PM – 9:00 PM"},"morning":{"cost":"~$109+/person (est.)","description":"Rope-drop Magic Kingdom: hit Fantasyland rides first (Peter Pan, Small World), then the classics. Take a midday break back at the hotel — you'll thank yourself at fireworks.","stop":"Magic Kingdom","time":"8:30 AM – 1:00 PM"},"title":"Disney Day 1"},{"afternoon":{"cost":"Free (est.)","description":"Midday hotel break — rest and swim before the evening.","stop":"Hotel pool break","time":"1:30 PM – 4:30 PM"},"day":2,"evening":{"cost":"$70–$110 for dinner (est.)","description":"Ride the Hogwarts Express to Islands of Adventure, explore Jurassic World and Seuss Landing, then dinner at CityWalk.","stop":"Islands of Adventure + CityWalk","time":"5:00 PM – 9:30 PM"},"morning":{"cost":"~$164+/person 2-park (est.)","description":"Universal Studios Florida: the Wizarding World of Diagon Alley, Transformers, and the Bourne stunt show. Two-park tickets let you ride the Hogwarts Express.","stop":"Universal Studios Florida","time":"9:00 AM – 1:30 PM"},"title":"Universal Day"},{"afternoon":{"cost":"Included (est.)","description":"Bus tour to the Apollo/Saturn V Center, then the Shuttle Launch Experience simulator and the play dome for little astronauts.","stop":"KSC continued","time":"1:00 PM – 5:00 PM"},"day":3,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Dinner back in Orlando — the drive is about an hour.","stop":"Dinner in Orlando","time":"6:30 PM – 8:30 PM"},"morning":{"cost":"$75/adult, $65/child (est.)","description":"Drive an hour east to NASA's visitor complex. Start with Space Shuttle Atlantis — the reveal is genuinely moving — then Heroes & Legends.","stop":"Kennedy Space Center","time":"9:00 AM – 12:30 PM"},"title":"Space Day"},{"afternoon":{"cost":"Free (est.)","description":"Drive home.","stop":"Departure","time":"3:00 PM – 5:00 PM"},"day":4,"evening":{"cost":"Free (est.)","description":"Home and unpack the LEGO sets.","stop":"Home","time":"7:00 PM – 9:00 PM"},"morning":{"cost":"~$99/person (est.)","description":"45 minutes to Winter Haven for rides, Miniland USA, and the LEGO Factory tour. Built for ages 2-12 — calmer and cheaper than the big parks.","stop":"LEGOLAND Florida","time":"10:00 AM – 2:00 PM"},"title":"LEGOLAND Day"}],"lat":28.5383,"lng":-81.3792,"overview":"Orlando is the theme-park capital of the world, and this 4-day trip hits all four heavyweights: Disney's Magic Kingdom, Universal's two parks, Kennedy Space Center, and LEGOLAND Florida. It's a big, thrilling, exhausting-in-the-best-way family trip — plan midday breaks and buy tickets ahead. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Disney Springs — shopping, dining, and the LEGO store, free entry","Kennedy Space Center (mostly covered exhibits)","ICON Park — the Wheel and SEA LIFE aquarium, from $29 (est.)"],"region":"Central Florida","related":["tampa-fl-city","miami-fl-city","atlanta-ga-city"],"restaurants":[{"detail":"Fast-casual BBQ in Disney Springs from James Beard-nominated chefs — brisket, butcher boards, and a kids' menu.","name":"The Polite Pig","price":"$$"},{"detail":"Beloved Florida BBQ chain founded in Winter Park — brisket, burnt ends, and homestyle sides; very family-friendly.","name":"4 Rivers Smokehouse","price":"$$"},{"detail":"Tapas-style art lounge on International Drive — shareable plates, live artists painting, and a fun bohemian vibe kids enjoy.","name":"Café Tu Tu Tango","price":"$$"}],"state":"FL","stateName":"Florida","tagline":"Four theme-park giants in four days — the ultimate family trip.","title":"Orlando, FL: Four-Day Theme-Park Trip","tripType":"theme park trip","imageAsset":"assets/southeast/orlando-fl-city/hero.jpg"},{"attractions":[{"description":"The famous stretch of Ocean Drive and white sand: pastel Art Deco buildings from the 1920s-30s, colorful lifeguard towers, and warm Atlantic water. Go early for parking, bring an umbrella, and walk the boardwalk at sunset.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=South+Beach+Miami+Beach+FL","name":"South Beach & Art Deco District","officialUrl":"https://www.miamiandbeaches.com","photos":["assets/southeast/miami-fl-city/attr1-1.jpg","assets/southeast/miami-fl-city/attr1-2.jpg","assets/southeast/miami-fl-city/attr1-3.jpg","assets/southeast/miami-fl-city/attr1-4.jpg"],"price":"Free (est.)"},{"description":"Florida's largest zoo with open, cage-free habitats: feed giraffes, ride the safari cycle, and cool off at the splash playground. Huge and shadeless in parts — rent a safari cycle and go early.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Zoo+Miami+FL","name":"Zoo Miami","officialUrl":"https://www.zoofoundation.org","photos":["assets/southeast/miami-fl-city/attr2-1.jpg","assets/southeast/miami-fl-city/attr2-2.jpg","assets/southeast/miami-fl-city/attr2-3.jpg","assets/southeast/miami-fl-city/attr2-4.jpg"],"price":"$22.95/adult, $18.95/child (est.)"},{"description":"A 1916 Italian Renaissance-style waterfront villa with ten acres of formal gardens, fountains, and a stone barge on Biscayne Bay. The gardens are magical for kids — mazes of hedges, grottos, and secret corners.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Vizcaya+Museum+%26+Gardens+Miami+FL","name":"Vizcaya Museum & Gardens","officialUrl":"https://vizcaya.org","photos":["assets/southeast/miami-fl-city/attr3-1.jpg","assets/southeast/miami-fl-city/attr3-2.jpg","assets/southeast/miami-fl-city/attr3-3.jpg","assets/southeast/miami-fl-city/attr3-4.jpg"],"price":"$22/adult, $10/child (est.)"},{"description":"Downtown Miami's science museum on Biscayne Bay: a three-level aquarium with a rooftop, a planetarium, and hands-on exhibits built for kids. A perfect air-conditioned day with the bay right outside.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Phillip+%26+Patricia+Frost+Museum+of+Science+Miami+FL","name":"Phillip & Patricia Frost Museum of Science","officialUrl":"https://www.frostscience.org","photos":["assets/southeast/miami-fl-city/attr4-1.jpg","assets/southeast/miami-fl-city/attr4-2.jpg","assets/southeast/miami-fl-city/attr4-3.jpg","assets/southeast/miami-fl-city/attr4-4.jpg"],"price":"$29.95/adult, $20.95/child (est.)"}],"bestSeason":"November–April","budget":1600,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days; lodging and gas not included.","days":3,"destination":"Miami, FL","driveNotes":"Miami is 3.5 hours from Orlando on the Florida Turnpike (tolls) and 1 hour from Fort Lauderdale on I-95. Parking on South Beach runs $20-$40/day (est.); downtown parking is easier on weekends. The MetroMover is free downtown. Summer is hot and rainy — plan outdoor time for mornings.","familyFriendly":"Best for ages 5+. South Beach and the zoo are toddler-friendly (shade and breaks needed); Vizcaya's gardens delight all ages but supervise near water features; Frost Science is built for kids. Afternoon thunderstorms are daily in summer — plan indoor backups.","heroPhoto":"assets/southeast/miami-fl-city/hero.jpg","highlights":["Swim under the pastel lifeguard towers of South Beach","Feed giraffes at Zoo Miami","Explore the secret gardens of Vizcaya","See sharks and stars at the Frost Museum","Walk Ocean Drive's Art Deco district at sunset"],"id":"miami-fl-city","interests":["beaches","family","museums","outdoors","food"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Walk the boardwalk and Ocean Drive's Art Deco blocks; stop for Cuban coffee and people-watch.","stop":"Ocean Drive walk","time":"3:00 PM – 6:00 PM"},"day":1,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Easy dinner on the beach side, then an early night.","stop":"South Beach dinner","time":"6:30 PM – 8:30 PM"},"morning":{"cost":"Free (est.)","description":"Arrive early, claim a spot near a lifeguard tower, and swim before the crowds. Rinse off at the beach showers.","stop":"South Beach","time":"9:00 AM – 1:00 PM"},"title":"Beach Day"},{"afternoon":{"cost":"$22.95/adult, $18.95/child (est.)","description":"Wander the formal gardens, find the secret maze, and picnic under the banyans. Supervise kids near the bay.","stop":"Vizcaya Museum & Gardens","time":"2:00 PM – 5:00 PM"},"day":2,"evening":{"cost":"$70–$100 for dinner (est.)","description":"Fried chicken and biscuits at a South Beach favorite.","stop":"Dinner at Yardbird","time":"6:30 PM – 8:30 PM"},"morning":{"cost":"$22.95/adult, $18.95/child (est.)","description":"Go at opening: feed giraffes, ride the safari cycle, and hit the splash playground before the heat.","stop":"Zoo Miami","time":"10:00 AM – 1:30 PM"},"title":"Zoo and Vizcaya"},{"afternoon":{"cost":"Free (est.)","description":"Drive home.","stop":"Departure","time":"3:00 PM – 5:00 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"Home and unpack.","stop":"Home","time":"7:00 PM – 9:00 PM"},"morning":{"cost":"$29.95/adult, $20.95/child (est.)","description":"Aquarium, planetarium show, and hands-on exhibits — the perfect air-conditioned finale on Biscayne Bay.","stop":"Frost Museum of Science","time":"10:00 AM – 2:00 PM"},"title":"Science Day"}],"lat":25.7617,"lng":-80.1918,"overview":"Miami is beaches, wildlife, and one very grand Italian villa. This 3-day trip mixes South Beach's famous sand with Zoo Miami, the fairy-tale gardens of Vizcaya, and the kid-built Frost Museum of Science. It's vibrant, sunny, and very family-doable with a little planning around the heat. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Frost Museum of Science (fully indoors)","Miami Children's Museum, $24/person (est.)","Pérez Art Museum Miami with its family programs, $18/adult (est.)"],"region":"South Florida","related":["orlando-fl-city","key-west-fl-coastal","tampa-fl-city"],"restaurants":[{"detail":"Miami Beach institution since 1913 — stone crab claws with mustard sauce; a classic splurge dinner.","name":"Joe's Stone Crab","price":"$$$"},{"detail":"Beloved South Beach sandwich counter — fresh French-style sandwiches and smoothies, perfect for a beach picnic.","name":"La Sandwicherie","price":"$"},{"detail":"Southern comfort food done right — famous fried chicken, biscuits, and mac and cheese in a family-friendly room.","name":"Yardbird Southern Table & Bar","price":"$$"}],"state":"FL","stateName":"Florida","tagline":"Beaches, wildlife, and one very grand villa — Miami with kids.","title":"Miami, FL: 3-Day Beach & City Trip","tripType":"beach and city trip","imageAsset":"assets/southeast/miami-fl-city/hero.jpg"},{"attractions":[{"description":"The heart of Old Town: stroll Duval Street's shops and cafés, then head to Mallory Square for the nightly Sunset Celebration — street performers, food carts, and the famous green flash over the Gulf. Best on foot or by bike.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Duval+Street+%26+Mallory+Square+Key+West+FL","name":"Duval Street & Mallory Square","officialUrl":"https://www.cityofkeywest-fl.gov","photos":["assets/southeast/key-west-fl-coastal/attr1-1.jpg","assets/southeast/key-west-fl-coastal/attr1-2.jpg","assets/southeast/key-west-fl-coastal/attr1-3.jpg","assets/southeast/key-west-fl-coastal/attr1-4.jpg"],"price":"Free (est.)"},{"description":"Hemingway's 1930s Spanish Colonial home with its famous six-toed cats, pool, and writing studio. Guided tours run about 30 minutes — kids love hunting for the cats, and the house is a cool midday break.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Hemingway+Home+Key+West+FL","name":"The Hemingway Home & Museum","officialUrl":"https://www.hemingwayhome.com","photos":["assets/southeast/key-west-fl-coastal/attr2-1.jpg","assets/southeast/key-west-fl-coastal/attr2-2.jpg","assets/southeast/key-west-fl-coastal/attr2-3.jpg","assets/southeast/key-west-fl-coastal/attr2-4.jpg"],"price":"$18/adult, $7/child (est.)"},{"description":"A full-day boat trip 70 miles west to a massive Civil War brick fort on a tropical island — snorkel the clear water, tour the fort, and watch sea turtles. Ferry books out weeks ahead; bring reef-safe sunscreen.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Dry+Tortugas+National+Park+FL","name":"Dry Tortugas National Park","officialUrl":"https://www.nps.gov/drto","photos":["assets/southeast/key-west-fl-coastal/attr3-1.jpg","assets/southeast/key-west-fl-coastal/attr3-2.jpg","assets/southeast/key-west-fl-coastal/attr3-3.jpg","assets/southeast/key-west-fl-coastal/attr3-4.jpg"],"price":"Ferry ~$190/adult, $135/child (est.)"},{"description":"A glass-domed tropical paradise with hundreds of free-flying butterflies, flamingos, and orchids. Magical for little kids — go early when the butterflies are most active, and bring the camera.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Key+West+Butterfly+%26+Nature+Conservatory+FL","name":"Key West Butterfly & Nature Conservatory","officialUrl":"https://www.keywestbutterfly.com","photos":["assets/southeast/key-west-fl-coastal/attr4-1.jpg","assets/southeast/key-west-fl-coastal/attr4-2.jpg","assets/southeast/key-west-fl-coastal/attr4-3.jpg","assets/southeast/key-west-fl-coastal/attr4-4.jpg"],"price":"$16.50/adult, $12.50/child (est.)"}],"bestSeason":"November–April","budget":1900,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days (Dry Tortugas ferry is the big cost); lodging and gas not included.","days":3,"destination":"Key West, FL","driveNotes":"Key West is 3.5 hours from Miami down the Overseas Highway (US-1) — the drive over the bridges is half the fun. Parking downtown is scarce and pricey (~$25/day, est.); bikes or the Duval Loop free bus are best in town. The Dry Tortugas ferry leaves from the Key West ferry terminal at 8 AM sharp.","familyFriendly":"Best for ages 6+. Duval Street, the butterfly conservatory, and Mallory Square suit all ages; Dry Tortugas is a long boat day best for older kids (no shade on the water); the Hemingway Home delights curious kids. Nights on Duval skew adult — plan family time earlier.","heroPhoto":"assets/southeast/key-west-fl-coastal/hero.jpg","highlights":["Watch the sunset at Mallory Square's Sunset Celebration","Meet the six-toed cats at the Hemingway Home","Snorkel around Civil War-era Fort Jefferson","Stand inside a cloud of butterflies","Drive the Overseas Highway over turquoise water"],"id":"key-west-fl-coastal","interests":["beaches","outdoors","historical-sites","family","nature"],"itinerary":[{"afternoon":{"cost":"$18/adult, $7/child (est.)","description":"Tour Hemingway's house and hunt for six-toed cats in the gardens.","stop":"Hemingway Home","time":"2:00 PM – 3:30 PM"},"day":1,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Join the Sunset Celebration at Mallory Square — performers, food carts, and the sunset over the Gulf.","stop":"Mallory Square sunset","time":"6:00 PM – 9:00 PM"},"morning":{"cost":"Free (est.)","description":"Stroll Duval Street, grab breakfast, and explore the shops of Old Town on foot.","stop":"Duval Street","time":"9:00 AM – 12:00 PM"},"title":"Old Town Day"},{"afternoon":{"cost":"Included in ferry (est.)","description":"Snorkel the clear water around the fort, tour the brick ramparts, and watch for sea turtles.","stop":"Fort Jefferson","time":"12:30 PM – 4:30 PM"},"day":2,"evening":{"cost":"$70–$100 for dinner (est.)","description":"Seafood dinner back in town.","stop":"Dinner in Key West","time":"7:00 PM – 9:00 PM"},"morning":{"cost":"Ferry ~$190/adult, $135/child (est.)","description":"Board the ferry at 8 AM for the 2.5-hour ride 70 miles west to Fort Jefferson. Book weeks ahead.","stop":"Dry Tortugas ferry","time":"8:00 AM – 10:30 AM"},"title":"Dry Tortugas Day"},{"afternoon":{"cost":"Free (est.)","description":"Drive the Overseas Highway home — stop at Bahia Honda State Park for a swim on the way.","stop":"Drive home","time":"2:00 PM – 5:30 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"Home.","stop":"Home","time":"7:00 PM – 9:00 PM"},"morning":{"cost":"$16.50/adult, $12.50/child (est.)","description":"Step inside the glass conservatory — hundreds of butterflies, flamingos, and orchids. Go early when butterflies are most active.","stop":"Butterfly Conservatory","time":"9:00 AM – 11:00 AM"},"title":"Butterflies and Home"}],"lat":24.5551,"lng":-81.78,"overview":"Key West is the end of the road — literally, at Mile 0 of US-1 — and worth every mile of the Overseas Highway drive. This 3-day trip blends Old Town charm, Hemingway's cats, a butterfly paradise, and a full-day boat trip to the Civil War fort at Dry Tortugas. It's laid-back, sunny, and full of only-in-the-Keys moments. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Key West Shipwreck Treasure Museum, $17/adult (est.)","Key West Aquarium, $19/adult (est.)","Truman Little White House tour, $24/adult (est.)"],"region":"Florida Keys","related":["miami-fl-city","st-augustine-fl-coastal","tampa-fl-city"],"restaurants":[{"detail":"Outdoor Caribbean café with roaming roosters — legendary breakfast and key lime pie in a tropical garden.","name":"Blue Heaven","price":"$$"},{"detail":"Cuban restaurant and bar by Mallory Square — ropa vieja, Cuban sandwiches, and live music with harbor views.","name":"El Meson de Pepe","price":"$$"},{"detail":"Tiny Duval Street shack — Maine lobster rolls, conch fritters, and fried clams; a fun casual lunch.","name":"DJ's Clam Shack","price":"$"}],"state":"FL","stateName":"Florida","tagline":"The end of the road — sunsets, six-toed cats, and a fort on the sea.","title":"Key West, FL: 3-Day Island Trip","tripType":"island trip","imageAsset":"assets/southeast/key-west-fl-coastal/hero.jpg"},{"attractions":[{"description":"The oldest masonry fort in the continental US, built by the Spanish in the 1600s. Climb the ramparts, watch cannon demonstrations, and explore the gun decks. The coquina walls are nearly indestructible — kids love the battle history.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Castillo+de+San+Marcos+St.+Augustine+FL","name":"Castillo de San Marcos","officialUrl":"https://www.nps.gov/casa","photos":["assets/southeast/st-augustine-fl-coastal/attr1-1.jpg","assets/southeast/st-augustine-fl-coastal/attr1-2.jpg","assets/southeast/st-augustine-fl-coastal/attr1-3.jpg","assets/southeast/st-augustine-fl-coastal/attr1-4.jpg"],"price":"$15/adult, kids free (est.)"},{"description":"A zoological park famous for its complete crocodile collection — every species of crocodilian in the world. Daily feedings, a zip line over the alligators, and Maximo, the 15-foot saltwater croc. A thrilling half day.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=St.+Augustine+Alligator+Farm+FL","name":"St. Augustine Alligator Farm Zoological Park","officialUrl":"https://alligatorfarm.com","photos":["assets/southeast/st-augustine-fl-coastal/attr2-1.jpg","assets/southeast/st-augustine-fl-coastal/attr2-2.jpg","assets/southeast/st-augustine-fl-coastal/attr2-3.jpg","assets/southeast/st-augustine-fl-coastal/attr2-4.jpg"],"price":"$34.99/adult, $21.99/child (est.)"},{"description":"Climb the 219 steps of this 1874 lighthouse for sweeping views of the coast and historic district. The maritime museum below has shipwreck artifacts and a kids' discovery area. Brave kids love the climb.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=St.+Augustine+Lighthouse+FL","name":"St. Augustine Lighthouse & Maritime Museum","officialUrl":"https://www.staugustinelighthouse.org","photos":["assets/southeast/st-augustine-fl-coastal/attr3-1.jpg","assets/southeast/st-augustine-fl-coastal/attr3-2.jpg","assets/southeast/st-augustine-fl-coastal/attr3-3.jpg","assets/southeast/st-augustine-fl-coastal/attr3-4.jpg"],"price":"$14.95/adult, $12.95/child (est.)"},{"description":"The pedestrian heart of the nation's oldest city: cobblestone lanes, Spanish colonial architecture, candy shops, and the old city gates. Ride the Old Town Trolley, browse the shops, and end with gelato.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=St.+George+Street+St.+Augustine+FL","name":"St. George Street & Old Town","officialUrl":"https://citystaug.com","photos":["assets/southeast/st-augustine-fl-coastal/attr4-1.jpg","assets/southeast/st-augustine-fl-coastal/attr4-2.jpg","assets/southeast/st-augustine-fl-coastal/attr4-3.jpg","assets/southeast/st-augustine-fl-coastal/attr4-4.jpg"],"price":"Free (est.)"}],"bestSeason":"October–May","budget":1100,"budgetNote":"Estimate for 2 adults + 2 kids over 2 days; lodging and gas not included.","days":2,"destination":"St. Augustine, FL","driveNotes":"St. Augustine is 45 minutes south of Jacksonville on I-95 and 2 hours from Orlando. Park in the downtown garage ($15/day, est.) — Old Town is walkable from there. The Alligator Farm and lighthouse are a 10-minute drive south on A1A. Summer afternoons bring storms; winter is perfect.","familyFriendly":"Great for ages 5+. The fort, lighthouse climb, and alligator farm are big hits with school-age kids; toddlers do fine at St. George Street and the beach. The lighthouse's 219 steps are not for small legs or the height-shy.","heroPhoto":"assets/southeast/st-augustine-fl-coastal/hero.jpg","highlights":["Explore the 1600s Castillo de San Marcos fort","See every crocodilian species on Earth","Climb 219 steps up the historic lighthouse","Wander cobblestone St. George Street","Swim at St. Augustine Beach"],"id":"st-augustine-fl-coastal","interests":["historical-sites","nature","family","beaches","food"],"itinerary":[{"afternoon":{"cost":"$14.95/adult, $12.95/child (est.)","description":"Climb the 219 steps of the 1874 lighthouse, explore the maritime museum, and let kids run in the discovery area.","stop":"St. Augustine Lighthouse","time":"2:00 PM – 4:30 PM"},"day":1,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Spanish-Cuban classics in a historic setting on St. George Street.","stop":"Dinner at Columbia Restaurant","time":"6:00 PM – 8:00 PM"},"morning":{"cost":"$15/adult, kids free (est.)","description":"Tour the 1600s Spanish fort: ramparts, cannon demos, and the gun deck. Arrive at opening to beat the heat.","stop":"Castillo de San Marcos","time":"9:00 AM – 11:30 AM"},"title":"Fort and Lighthouse Day"},{"afternoon":{"cost":"Free (est.)","description":"Ride the Old Town Trolley, shop St. George Street, and grab gelato before the drive home.","stop":"Old Town and departure","time":"1:00 PM – 4:00 PM"},"day":2,"evening":{"cost":"Free (est.)","description":"Home.","stop":"Home","time":"6:00 PM – 8:00 PM"},"morning":{"cost":"$34.99/adult, $21.99/child (est.)","description":"Feedings, the zip line, and Maximo the giant saltwater croc. A thrilling half day.","stop":"Alligator Farm","time":"9:00 AM – 12:30 PM"},"title":"Gators and Old Town"}],"lat":29.8942,"lng":-81.3144,"overview":"St. Augustine is the oldest city in the US — 450+ years of Spanish forts, cobblestone streets, and pirate lore. This 2-day trip packs in the 1600s Castillo fort, the alligator farm's crocodile collection, a lighthouse climb, and the charming lanes of Old Town. History that kids actually enjoy. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Lightner Museum's eclectic collections, $12/adult (est.)","Pirate & Treasure Museum, $15/adult (est.)","Oldest Wooden School House, $6/adult (est.)"],"region":"Northeast Florida","related":["jekyll-island-ga-coastal","orlando-fl-city","tampa-fl-city"],"restaurants":[{"detail":"Southern classics with a Florida twist — shrimp and grits and farm-to-table plates in a lively downtown room.","name":"The Floridian","price":"$$"},{"detail":"Fresh, locally sourced seafood in the heart of downtown — fish tacos, shrimp and grits, and a cozy vibe.","name":"Catch 27","price":"$$"},{"detail":"Florida's oldest restaurant (1905) — Spanish-Cuban classics like paella and the famous 1905 Salad on St. George Street.","name":"Columbia Restaurant","price":"$$"}],"state":"FL","stateName":"Florida","tagline":"The nation's oldest city — forts, gators, and cobblestone streets.","title":"St. Augustine, FL: 2-Day History Trip","tripType":"history trip","imageAsset":"assets/southeast/st-augustine-fl-coastal/hero.jpg"},{"attractions":[{"description":"One of America's best theme parks: world-class coasters (Iron Gwazi, SheiKra) plus real animal habitats — giraffes, lions, and a Serengeti safari ride. Split the day: coasters in the morning, animals in the cooler afternoon.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Busch+Gardens+Tampa+FL","name":"Busch Gardens Tampa Bay","officialUrl":"https://www.buschgardens.com","photos":["assets/southeast/tampa-fl-city/attr1-1.jpg","assets/southeast/tampa-fl-city/attr1-2.jpg","assets/southeast/tampa-fl-city/attr1-3.jpg","assets/southeast/tampa-fl-city/attr1-4.jpg"],"price":"~$119/person (est.)"},{"description":"Downtown Tampa's aquarium with a two-story coral reef tank, sharks, sea turtles, and a splash pad for little ones. The dolphin cruise add-on and the outdoor Wild Dolphin Cruise are worth it.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=The+Florida+Aquarium+Tampa+FL","name":"The Florida Aquarium","officialUrl":"https://www.flaquarium.org","photos":["assets/southeast/tampa-fl-city/attr2-1.jpg","assets/southeast/tampa-fl-city/attr2-2.jpg","assets/southeast/tampa-fl-city/attr2-3.jpg","assets/southeast/tampa-fl-city/attr2-4.jpg"],"price":"$34.95/adult, $24.95/child (est.)"},{"description":"A beloved zoo with animal encounters galore: feed giraffes, ride the safari, and cool off at the water play areas. The manatee critical care center is a unique, heartwarming stop. Great for a half day.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=ZooTampa+FL","name":"ZooTampa at Lowry Park","officialUrl":"https://www.zootampa.org","photos":["assets/southeast/tampa-fl-city/attr3-1.jpg","assets/southeast/tampa-fl-city/attr3-2.jpg","assets/southeast/tampa-fl-city/attr3-3.jpg","assets/southeast/tampa-fl-city/attr3-4.jpg"],"price":"$44.95/adult, $34.95/child (est.)"},{"description":"America's best beach, 30 minutes west of Tampa: powder-white sand, calm Gulf water, and the famous Pier 60 sunset. Arrive before 10 AM for parking, stay for the nightly sunset festival with street performers.","mapsUrl":"https://www.google.com/maps/search/?api=1&query=Clearwater+Beach+FL","name":"Clearwater Beach","officialUrl":"https://www.visitstpeteclearwater.com/communities/clearwater","photos":["assets/southeast/tampa-fl-city/attr4-1.jpg","assets/southeast/tampa-fl-city/attr4-2.jpg","assets/southeast/tampa-fl-city/attr4-3.jpg","assets/southeast/tampa-fl-city/attr4-4.jpg"],"price":"Free (est.)"}],"bestSeason":"October–May","budget":1500,"budgetNote":"Estimate for 2 adults + 2 kids over 3 days; lodging and gas not included.","days":3,"destination":"Tampa & Clearwater, FL","driveNotes":"Tampa is 1.5 hours from Orlando on I-4 and 4 hours from Miami on I-75. Clearwater Beach is 30 minutes west via the Courtney Campbell Causeway. Parking at Busch Gardens is about $30 (est.); Clearwater Beach fills by 10 AM on weekends. The Tampa Riverwalk connects downtown attractions.","familyFriendly":"Great for ages 4+. Busch Gardens has rides for all heights (check the height chart first); the aquarium and ZooTampa are perfect for toddlers; Clearwater Beach's calm water is ideal for little swimmers. Summer is hot — hydrate and take shade breaks.","heroPhoto":"assets/southeast/tampa-fl-city/hero.jpg","highlights":["Ride world-class coasters at Busch Gardens","Meet sea turtles at The Florida Aquarium","Feed giraffes at ZooTampa","Swim the white sand of Clearwater Beach","Watch the sunset at Pier 60"],"id":"tampa-fl-city","interests":["beaches","family","amusement-parks","nature","food"],"itinerary":[{"afternoon":{"cost":"Free (est.)","description":"Feed giraffes, ride the safari, and cool off at the water play areas. The manatee center is a must.","stop":"ZooTampa","time":"2:00 PM – 5:00 PM"},"day":1,"evening":{"cost":"$70–$100 for dinner (est.)","description":"Waterfront dinner on the Riverwalk — native Florida fare.","stop":"Dinner at Ulele","time":"6:30 PM – 8:30 PM"},"morning":{"cost":"$34.95/adult, $24.95/child (est.)","description":"Coral reef tank, sharks, sea turtles, and the splash pad. Arrive at opening for the quietest hour.","stop":"The Florida Aquarium","time":"9:30 AM – 1:00 PM"},"title":"Aquarium and Zoo Day"},{"afternoon":{"cost":"Free (est.)","description":"Stay for the Pier 60 sunset festival — street performers and craft vendors as the sun drops.","stop":"Pier 60 sunset","time":"5:00 PM – 8:00 PM"},"day":2,"evening":{"cost":"$60–$90 for dinner (est.)","description":"Beachfront seafood after sunset.","stop":"Dinner on the beach","time":"8:00 PM – 9:30 PM"},"morning":{"cost":"Free (est.)","description":"Drive 30 minutes to America's best beach. Claim a spot early, swim the calm Gulf water, and build sandcastles.","stop":"Clearwater Beach","time":"9:00 AM – 4:00 PM"},"title":"Beach Day"},{"afternoon":{"cost":"Free (est.)","description":"Drive home.","stop":"Departure","time":"4:00 PM – 6:00 PM"},"day":3,"evening":{"cost":"Free (est.)","description":"Home.","stop":"Home","time":"8:00 PM – 9:30 PM"},"morning":{"cost":"~$119/person (est.)","description":"A full day of coasters and animal habitats — Iron Gwazi for the brave, the Serengeti safari for everyone. Go at opening.","stop":"Busch Gardens Tampa Bay","time":"10:00 AM – 3:00 PM"},"title":"Busch Gardens Day"}],"lat":27.9506,"lng":-82.4572,"overview":"Tampa pairs big-city thrills with one of America's best beaches. This 3-day trip hits Busch Gardens' world-class coasters, The Florida Aquarium, ZooTampa, and the powder-white sand of Clearwater Beach. It's an easy, sunny, action-packed family weekend. All prices and hours below are estimates — verify before you go, as seasonal schedules change.","rainyDay":["Tampa Museum of Art, $25/adult (est.)","Glazer Children's Museum, $18/person (est.)","MOSI (Museum of Science & Industry), $18/adult (est.)"],"region":"Tampa Bay","related":["orlando-fl-city","miami-fl-city","key-west-fl-coastal"],"restaurants":[{"detail":"Tampa legend since 1956 — impeccable steaks and a famous dessert room upstairs; a splurge night out.","name":"Bern's Steak House","price":"$$$"},{"detail":"Waterfront on the Riverwalk — native Florida fare like alligator hush puppies and cedar plank salmon.","name":"Ulele","price":"$$"},{"detail":"Florida's oldest restaurant (1905) in historic Ybor City — Spanish-Cuban classics and flamenco dancing.","name":"Columbia Restaurant","price":"$$"}],"state":"FL","stateName":"Florida","tagline":"Coasters, critters, and America's best beach.","title":"Tampa & Clearwater, FL: 3-Day Thrills Trip","tripType":"theme park and beach trip","imageAsset":"assets/southeast/tampa-fl-city/hero.jpg"}];
